import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { Card, Button, Input, App, Spin } from "../components/admin-ui";
import { AdminShell } from "../layouts/AdminShell";
import { useLegalDocuments, useSaveLegalDocument } from "../api/hooks";
import { MarkdownLite } from "../components/MarkdownLite";
import type { LegalAppScope, LegalDocType } from "@kawkaw/shared";

const APP_SCOPES: LegalAppScope[] = ["admin", "pos", "stall", "customer"];
const DOC_TYPES: LegalDocType[] = ["terms", "privacy"];

export function LegalContentScreen() {
  const { t, i18n } = useTranslation();
  const { message } = App.useApp();
  const { data, isLoading } = useLegalDocuments();
  const save = useSaveLegalDocument();

  const [appScope, setAppScope] = useState<LegalAppScope>("customer");
  const [docType, setDocType] = useState<LegalDocType>("terms");
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  const docs = data?.data ?? [];
  const active = useMemo(
    () => docs.find((d) => d.app_scope === appScope && d.doc_type === docType) ?? null,
    [docs, appScope, docType],
  );

  useEffect(() => {
    setTitle(active?.title ?? "");
    setContent(active?.content ?? "");
  }, [active]);

  const appLabel = (scope: LegalAppScope) =>
    ({ admin: t("legalContent.appAdmin"), pos: t("legalContent.appPos"), stall: t("legalContent.appStall"), customer: t("legalContent.appCustomer") }[scope]);
  const docLabel = (type: LegalDocType) => (type === "terms" ? t("legalContent.docTerms") : t("legalContent.docPrivacy"));

  const onSave = async () => {
    try {
      await save.mutateAsync({ appScope, docType, title: title.trim() || docLabel(docType), content });
      void message.success(t("legalContent.saveSuccess"));
    } catch {
      void message.error(t("legalContent.saveFailed"));
    }
  };

  return (
    <AdminShell>
      <div className="min-h-screen bg-[#f8f9fa] px-8 pb-10 pt-7">
        <div className="mx-auto max-w-[1100px]">
          <div className="mb-[22px]">
            <h1 className="m-0 text-[32px] font-black leading-[1.1] text-[#191c1d]">{t("legalContent.title")}</h1>
            <p className="mt-2 max-w-2xl text-sm text-[#737373]">{t("legalContent.subtitle")}</p>
          </div>

          {isLoading ? (
            <div className="p-10 text-center"><Spin /></div>
          ) : (
            <>
              <div className="mb-4 flex flex-wrap gap-2">
                {APP_SCOPES.map((scope) => (
                  <button
                    key={scope}
                    type="button"
                    onClick={() => setAppScope(scope)}
                    className={`cursor-pointer rounded-full border px-4 py-2 text-sm font-extrabold transition ${
                      appScope === scope ? "border-[#ea580c] bg-[#fff7ed] text-[#ea580c]" : "border-[#e5e7eb] bg-white text-[#525252] hover:border-[#fdba74]"
                    }`}
                  >
                    {appLabel(scope)}
                  </button>
                ))}
              </div>
              <div className="mb-6 flex flex-wrap gap-2">
                {DOC_TYPES.map((type) => (
                  <button
                    key={type}
                    type="button"
                    onClick={() => setDocType(type)}
                    className={`cursor-pointer rounded-full border px-4 py-1.5 text-[13px] font-bold transition ${
                      docType === type ? "border-[#191c1d] bg-[#191c1d] text-white" : "border-[#e5e7eb] bg-white text-[#525252] hover:border-[#a3a3a3]"
                    }`}
                  >
                    {docLabel(type)}
                  </button>
                ))}
              </div>

              <div className="grid grid-cols-1 gap-5 min-[900px]:grid-cols-2">
                <Card className="overflow-hidden rounded-2xl border border-[#e5e7eb] shadow-[0_14px_34px_rgba(15,23,42,0.05)]">
                  <div className="p-5">
                    <label className="mb-1.5 block text-xs font-black uppercase text-[#737373]">{t("legalContent.titleLabel")}</label>
                    <Input value={title} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setTitle(e.target.value)} className="mb-4" />

                    <label className="mb-1.5 block text-xs font-black uppercase text-[#737373]">{t("legalContent.contentLabel")}</label>
                    <Input.TextArea
                      value={content}
                      onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setContent(e.target.value)}
                      rows={16}
                      className="mb-2 font-mono text-[13px]"
                    />
                    {!content.trim() && <p className="mb-3 text-xs text-[#a3a3a3]">{t("legalContent.unsavedContentHint")}</p>}

                    <div className="mb-4 text-xs text-[#a3a3a3]">
                      {active?.updated_at ? t("legalContent.lastUpdated", { date: new Date(active.updated_at).toLocaleString(i18n.language) }) : t("legalContent.neverUpdated")}
                    </div>

                    <Button type="primary" loading={save.isPending} onClick={() => void onSave()}>
                      {t("legalContent.save")}
                    </Button>
                  </div>
                </Card>

                <Card className="overflow-hidden rounded-2xl border border-[#e5e7eb] shadow-[0_14px_34px_rgba(15,23,42,0.05)]">
                  <div className="p-5">
                    <div className="mb-3 text-xs font-black uppercase text-[#737373]">{t("legalContent.preview")}</div>
                    <div className="mb-3 text-lg font-black text-[#191c1d]">{title || docLabel(docType)}</div>
                    {content.trim() ? <MarkdownLite content={content} /> : <p className="text-sm italic text-[#a3a3a3]">{t("legalContent.unsavedContentHint")}</p>}
                  </div>
                </Card>
              </div>
            </>
          )}
        </div>
      </div>
    </AdminShell>
  );
}
