/**
 * Fetches every order matching the given filters (not just the current
 * page) for CSV export — the Orders screen paginates, but an export needs
 * every matching row.
 */
export async function fetchAdminOrdersForExport(params: Record<string, string | number | undefined>) {
  const sp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) { if (v != null && k !== "page" && k !== "limit") sp.set(k, String(v)); }
  sp.set("limit", "200"); // GET /admin/orders caps limit at 200
  const res = await api().get(`admin/orders?${sp}`).json<PagedOk<Order>>();
  return res.data.items ?? [];
}

