export function useCreateMenuItem() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: Record<string, unknown>) => {
      const payload = { ...body };
      // Ensure numeric fields are numbers
      if (payload.price != null) payload.price = Number(payload.price);
      if (payload.offer_price != null) payload.offer_price = Number(payload.offer_price);
      // Remove display-only fields
      delete payload.option_groups; // managed separately
      delete payload.categories; // managed via category_ids
      return api().post("admin/menu/items", { json: payload }).json();
    },
    onSuccess: () => { void qc.invalidateQueries({ queryKey: ["admin", "menu"] }); },
  });
}

