export function useCreateStaff() {
  const qc = useQueryClient();
  return useMutation({
    // Backend's Zod schema expects `stall_id` (snake_case) — silently dropped
    // (never persisted) if sent as `stallId`, since z.object().parse() strips
    // unrecognized keys with no error. Translate at the boundary so callers can
    // keep using the app's normal camelCase convention.
    mutationFn: ({ stallId, ...body }: { name: string; phone: string; role: string; stallId?: string; pin: string }) =>
      api().post("admin/staff", { json: { ...body, stall_id: stallId || undefined } }).json(),
    onSuccess: () => { void qc.invalidateQueries({ queryKey: ["admin", "staff"] }); },
  });
}

