export function useNotifications() {
  return useQuery({
    queryKey: ["notifications"],
    // The backend wraps the list payload as reply.ok({ data, unreadCount }),
    // so unlike other ApiOk<T[]> endpoints here, the array is nested one level
    // deeper at .data.data, with unreadCount alongside it at .data.unreadCount.
    queryFn: () =>
      api().get("staff/notifications", { searchParams: { limit: 20 } })
        .json<ApiOk<{ data: AdminNotification[]; unreadCount: number }>>(),
    // Socket "rider:status_changed" invalidates this on a failed-delivery event;
    // this interval is just the safety net for missed/late socket events.
    refetchInterval: 30_000,
  });
}

