// @ts-nocheck
import { useState } from "react";
import { Button, DatePicker, Input, Select } from "../components/admin-ui";
import {
  DownloadOutlined, FilterOutlined, SearchOutlined,
} from "../components/admin-icons";
import type { ColumnsType } from "../components/admin-ui";
import type { ActivityLog } from "@kawkaw/shared";
import { useTranslation } from "react-i18next";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import { useActivityLog } from "../api/hooks";
import { formatDateTimeWithSeconds } from "../utils/formatLocaleDate";

const { RangePicker } = DatePicker;

/* ── Action pill colours ─────────────────────────── */
const ACTION_STYLE: Record<string, { bg: string; color: string }> = {
  create:    { bg: T.successBg, color: T.successText },
  update:    { bg: T.surfaceBlue, color: T.infoDark },
  delete:    { bg: T.dangerBg, color: T.dangerText },
  login:     { bg: T.purpleBg, color: T.purpleText },
  logout:    { bg: T.surfaceSection, color: T.textBody },
  refund:    { bg: T.brandLight, color: T.brandWarm },
  reset_pin: { bg: T.warningBg, color: T.brandAmberText },
};

function ActionPill({ action }: { action: string }) {
  const s = ACTION_STYLE[action] ?? { bg: T.surfaceSection, color: T.textBody };
  return (
    <span style={{
      display: "inline-block", padding: "3px 10px", borderRadius: 20,
      fontSize: 11, fontWeight: 700, letterSpacing: 0.4,
      background: s.bg, color: s.color,
    }}>
      {action.replace("_", " ").toUpperCase()}
    </span>
  );
}

/* ── Screen ──────────────────────────────────────── */
export function ActivityLogScreen() {
  const { t, i18n } = useTranslation();
  const [page, setPage]           = useState(1);
  const [search, setSearch]       = useState("");
  const [action, setAction]       = useState<string | undefined>();
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);

  const { data, isLoading } = useActivityLog({
    page, limit: 10,
    q: search || undefined,
    action,
    from: dateRange?.[0],
    to: dateRange?.[1],
  });

  const columns: ColumnsType<ActivityLog> = [
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("activity.colStaff").toUpperCase()}</span>,
      key: "staff", width: 160,
      render: (_, row) => {
        const r = row as unknown as { staff?: { name: string } };
        const name = r.staff?.name ?? t("common.system");
        return <span style={{ fontSize: 14, fontWeight: 600, color: T.textDark }}>{name}</span>;
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("activity.colAction").toUpperCase()}</span>,
      dataIndex: "action", key: "action", width: 130,
      render: (v: string) => <ActionPill action={v} />,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("activity.colEntity").toUpperCase()}</span>,
      key: "entity", width: 180,
      render: (_, row) => {
        const r = row as unknown as { entity_type?: string; entity_id?: string };
        if (!r.entity_type) return <span style={{ color: T.textMuted }}>—</span>;
        return (
          <span style={{ fontSize: 13 }}>
            <span style={{ color: T.textDark, fontWeight: 600 }}>{r.entity_type}</span>
            {r.entity_id && (
              <span style={{ marginLeft: 6, padding: "1px 6px", background: T.surfaceSection, borderRadius: 4, fontSize: 11, color: T.textBody, fontFamily: "monospace" }}>
                {r.entity_id.slice(-8)}
              </span>
            )}
          </span>
        );
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("activity.colDetails").toUpperCase()}</span>,
      dataIndex: "meta", key: "desc",
      render: (v: Record<string, unknown> | null) =>
        v && Object.keys(v).length > 0
          ? <span style={{ fontSize: 12, color: T.textBody, fontFamily: "monospace", wordBreak: "break-all" }}>{JSON.stringify(v)}</span>
          : <span style={{ color: T.textMuted }}>—</span>,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("activity.colIp").toUpperCase()}</span>,
      dataIndex: "ip", key: "ip", width: 140,
      render: (v: string | null) =>
        v
          ? <span style={{ padding: "2px 8px", background: T.surfaceSection, borderRadius: 6, fontSize: 12, fontFamily: "monospace", color: T.textBody }}>{v}</span>
          : <span style={{ color: T.textMuted }}>—</span>,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: T.textMuted }}>{t("activity.colTime").toUpperCase()}</span>,
      dataIndex: "created_at", key: "time", width: 168,
      render: (v: string) => (
        <span style={{ fontSize: 13, color: T.textBody }}>
          {formatDateTimeWithSeconds(v, i18n.language)}
        </span>
      ),
      sorter: true,
    },
  ];

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px 40px", background: T.bg, minHeight: "100vh" }}>
        <div style={{ maxWidth: 1480, margin: "0 auto" }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", gap: 18, marginBottom: 22, flexWrap: "wrap" }}>
        <div>
          <div style={{ display: "inline-flex", alignItems: "center", padding: "6px 12px", borderRadius: 999, background: T.brandLight, color: T.brand, fontSize: 11, fontWeight: 900, textTransform: "uppercase", marginBottom: 10 }}>
            {data?.meta.total ?? 0}
          </div>
          <h1 style={{ margin: 0, fontSize: 32, lineHeight: 1.1, fontWeight: 900, color: T.textDark }}>{t("activity.title")}</h1>
          {data?.meta.total != null && (
            <div style={{ fontSize: 13, color: T.textMuted, marginTop: 2 }}>
              {t("activity.eventsRecorded", { count: data.meta.total })}
            </div>
          )}
        </div>
        <Button icon={<DownloadOutlined />}
          onClick={() => {
            const rows = data?.data ?? [];
            const header = ["Time", "Staff", "Action", "Entity Type", "Entity ID", "IP"];
            const csvRows = rows.map((r) => [
              new Date(r.created_at).toISOString(),
              r.staff?.name ?? "",
              r.action,
              r.entity_type,
              r.entity_id,
              r.ip ?? "",
            ].map((v) => `"${String(v).replace(/"/g, '""')}"`).join(","));
            const csv = [header.join(","), ...csvRows].join("\n");
            const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `activity-log-${new Date().toISOString().slice(0, 10)}.csv`;
            a.click();
            URL.revokeObjectURL(url);
          }}
          style={{ height: 44, borderRadius: 10, fontWeight: 700, fontSize: 14, borderColor: T.border, color: T.textBody, paddingInline: 20 }}>
          {t("activity.exportCsv")}
        </Button>
      </div>

      {/* Filter bar */}
      <div style={{ display: "flex", gap: 12, marginBottom: 20, flexWrap: "wrap", alignItems: "center", background: T.surface, border: "1px solid #E5E7EB", borderRadius: 16, padding: "18px 20px", boxShadow: "0 12px 28px rgba(15,23,42,0.04)" }}>
        <Input
          prefix={<SearchOutlined style={{ color: T.textMuted }} />}
          placeholder={t("activity.searchPlaceholder")}
          value={search}
          onChange={e => setSearch(e.target.value)}
          allowClear
          style={{ height: 44, borderRadius: 10, fontSize: 14, width: 280 }}
        />
        <Select
          placeholder={
            <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <FilterOutlined style={{ color: T.textMuted }} />
              <span style={{ color: T.textMuted }}>{t("activity.allActions")}</span>
            </span>
          }
          allowClear
          value={action}
          onChange={v => { setAction(v as string | undefined); setPage(1); }}
          style={{ height: 44, borderRadius: 10, width: 170 }}
          options={["create","update","delete","login","logout","refund","reset_pin"].map(a => ({
            value: a,
            label: <ActionPill action={a} />,
          }))}
        />
        <RangePicker
          showTime
          onChange={(_, s) => {
            setDateRange(s[0] && s[1] ? [s[0], s[1]] : null);
            setPage(1);
          }}
          style={{ height: 44, borderRadius: 10, fontSize: 14 }}
        />
        {(search || action || dateRange) && (
          <button
            type="button"
            onClick={() => { setSearch(""); setAction(undefined); setDateRange(null); setPage(1); }}
            style={{ border: "none", background: "transparent", color: T.brand, fontSize: 13, fontWeight: 700, cursor: "pointer", padding: "0 4px" }}
          >
            {t("activity.clearFilters")}
          </button>
        )}
      </div>

      {/* Table */}
      <div style={{ background: T.surface, borderRadius: 16, border: "1px solid #E5E7EB", overflow: "hidden", boxShadow: "0 14px 34px rgba(15,23,42,0.05)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #F3F4F6" }}>
          <div style={{ fontSize: 16, fontWeight: 900, color: T.textDark }}>{t("activity.title")}</div>
          <div style={{ fontSize: 12, fontWeight: 700, color: T.textMuted }}>{data?.meta.total ?? 0}</div>
        </div>
        <DataTable<ActivityLog>
          columns={columns}
          dataSource={data?.data ?? []}
          loading={isLoading}
          sticky={false}
          pagination={{
            current: page,
            total: data?.meta.total ?? 0,
            pageSize: 10,
            onChange: (p) => setPage(p),
          }}
        />
      </div>
        </div>
      </div>
    </AdminShell>
  );
}
