/**
 * "Test Print" against a real thermal printer isn't wired yet (would need a
 * local print-server bridge, out of scope here) — until then, this generates
 * a real PDF sized to the configured paper width so the store can hand it to
 * different kitchen printers to check which one actually fits/reads it,
 * rather than the button silently doing nothing.
 */
function handleTestPrint({ printerName, connType, printerIp, paperWidth }: {
  printerName: string; connType: string; printerIp: string; paperWidth: "58mm" | "80mm";
}) {
  const widthMm = paperWidth === "58mm" ? 58 : 80;
  const doc = new jsPDF({ unit: "mm", format: [widthMm, 150] });
  const cx = widthMm / 2;
  let y = 10;
  doc.setFontSize(11).setFont("courier", "bold");
  doc.text("TEST PRINT", cx, y, { align: "center" }); y += 6;
  doc.setFontSize(8).setFont("courier", "normal");
  doc.text(new Date().toLocaleString(), cx, y, { align: "center" }); y += 6;
  doc.text("-".repeat(paperWidth === "58mm" ? 32 : 42), cx, y, { align: "center" }); y += 5;
  const line = (label: string, value: string) => { doc.text(`${label}: ${value || "—"}`, 4, y); y += 5; };
  line("Printer name", printerName);
  line("Connection", connType);
  line("IP / address", printerIp);
  line("Paper width", paperWidth);
  y += 2;
  doc.text("-".repeat(paperWidth === "58mm" ? 32 : 42), cx, y, { align: "center" }); y += 6;
  doc.setFontSize(7);
  doc.text("If this page's width matches your", cx, y, { align: "center" }); y += 4;
  doc.text("printer's paper roll and text is legible,", cx, y, { align: "center" }); y += 4;
  doc.text("this printer/paper-width combo works.", cx, y, { align: "center" });
  doc.save(`test-print-${paperWidth}-${Date.now()}.pdf`);
}

/* ── Operating hours ─────────────────────────────── */
const DAYS = ["monday","tuesday","wednesday","thursday","friday","saturday","sunday"] as const;
type Day = (typeof DAYS)[number];
// Backend day_of_week follows JS Date.getDay() convention (0=Sunday..6=Saturday),
// while this screen's DAYS array is Monday-first for display purposes.
const DAY_TO_INDEX: Record<Day, number> = {
  monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6, sunday: 0,
};
type DaySchedule = { enabled: boolean; from: Dayjs; to: Dayjs };
const DEFAULT_HOURS: Record<Day, DaySchedule> = {
  monday:    { enabled:true,  from:dayjs("08:00","HH:mm"), to:dayjs("22:00","HH:mm") },
  tuesday:   { enabled:true,  from:dayjs("08:00","HH:mm"), to:dayjs("22:00","HH:mm") },
  wednesday: { enabled:true,  from:dayjs("08:00","HH:mm"), to:dayjs("22:00","HH:mm") },
  thursday:  { enabled:true,  from:dayjs("08:00","HH:mm"), to:dayjs("22:00","HH:mm") },
  friday:    { enabled:true,  from:dayjs("08:00","HH:mm"), to:dayjs("23:30","HH:mm") },
  saturday:  { enabled:true,  from:dayjs("09:00","HH:mm"), to:dayjs("23:30","HH:mm") },
  sunday:    { enabled:false, from:dayjs("00:00","HH:mm"), to:dayjs("08:00","HH:mm") },
};

/* ── Helpers ─────────────────────────────────────── */
function SectionCard({ icon, title, extra, children }: {
  icon: React.ReactNode; title: string; extra?: React.ReactNode; children: React.ReactNode;
}) {
  return (
    <div style={{ background:T.surface, borderRadius:16, border:"1px solid #E5E7EB", padding:"20px 22px", marginBottom:20, boxShadow:"0 12px 28px rgba(15,23,42,0.04)" }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:18 }}>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <span style={{ color:T.brand, fontSize:18 }}>{icon}</span>
          <span style={{ fontSize:16, fontWeight:800, color:T.textDark }}>{title}</span>
        </div>
        {extra}
      </div>
      {children}
    </div>
  );
}
