// @ts-nocheck
import { useState } from "react";
import {
  Button, Modal, Drawer, Form, Input, InputNumber, Switch,
  Typography, Space, Tag, Tooltip, App,
} from "../components/admin-ui";
import { EditOutlined, PlusOutlined } from "../components/admin-icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "../components/admin-ui";
import type { Stall } from "@kawkaw/shared";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { tokens } from "../styles/tokens";
import { useAdminStalls, useUpdateStall, useCreateStall } from "../api/hooks";

const { Title } = Typography;
const { color: T } = tokens;
const C = {
  brand: T.brand,
  textPrimary: T.textDark,
  textMuted: T.textMuted,
};

// ─── Section header used in the Add Stall modal ─────────────────────────────
function SectionHeader({ icon, label }: { icon: React.ReactNode; label: string }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16, marginTop: 4 }}>
      <div style={{
        width: 28, height: 28, borderRadius: "50%",
        display: "flex", alignItems: "center", justifyContent: "center",
        fontSize: 14,
      }}>
        {icon}
      </div>
      <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: C.textPrimary, textTransform: "uppercase" }}>
        {label}
      </span>
    </div>
  );
}

// ─── Add Stall Drawer (Figma 57-1546) ───────────────────────────────────────
type AddStallValues = {
  name: string;
  description?: string | null;
  is_open: boolean;
  sort_order: number;
};

function AddStallModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [form] = Form.useForm<AddStallValues>();
  const createStall = useCreateStall();

  const onFinish = async (values: AddStallValues) => {
    try {
      await createStall.mutateAsync({
        name: values.name,
        description: values.description ?? null,
        is_open: values.is_open,
        sort_order: values.sort_order,
      });
      void message.success(t("stalls.createSuccess"));
      form.resetFields();
      onClose();
    } catch {
      void message.error(t("stalls.createFailed"));
    }
  };

  const handleDiscard = () => {
    form.resetFields();
    onClose();
  };

  return (
    <Drawer
      open={open}
      onClose={handleDiscard}
      placement="right"
      width={420}
      title={<span style={{ fontSize: 18, fontWeight: 800, color: T.textDark }}>{t("stalls.addStall")}</span>}
      footer={null}
      closeIcon={<span style={{ fontSize: 18, color: T.textMuted }}>×</span>}
      styles={{ body: { padding: "20px 24px" } }}
    >
      <Form
        form={form}
        layout="vertical"
        onFinish={onFinish}
        initialValues={{ is_open: true, sort_order: 1 }}
        style={{ paddingTop: 8 }}
      >
        {/* ── BASIC INFO ────────────────────────────── */}
        <SectionHeader
          icon={<span style={{ fontSize: 16, background: T.brandLight, borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center" }}>ℹ️</span>}
          label={t("stalls.basicInfo")}
        />
        <Form.Item
          name="name"
          label={<span style={{ fontWeight: 600, fontSize: 13, color: C.textPrimary }}>{t("stalls.stallName")} <span style={{ color: T.dangerText }}>*</span></span>}
          rules={[{ required: true, message: t("stalls.stallNameRequired") }, { max: 120 }]}
          style={{ marginBottom: 16 }}
        >
          <Input
            placeholder={t("stalls.stallNamePlaceholder")}
            maxLength={120}
            style={{ borderRadius: 10, height: 44, fontSize: 14, color: T.textDark }}
          />
        </Form.Item>
        <Form.Item
          name="description"
          label={<span style={{ fontWeight: 600, fontSize: 13, color: C.textPrimary }}>{t("stalls.description")}</span>}
          style={{ marginBottom: 24 }}
        >
          <Input.TextArea
            placeholder={t("stalls.descriptionPlaceholder")}
            maxLength={400}
            rows={3}
            style={{ borderRadius: 10, fontSize: 14, resize: "none", color: T.textDark }}
          />
        </Form.Item>

        <div style={{ borderTop: "1px solid #F3F4F6", marginBottom: 20 }} />

        {/* ── STATUS ────────────────────────────────── */}
        <SectionHeader
          icon={<span style={{ fontSize: 16, background: T.surfaceGreen, borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center" }}>⚡</span>}
          label={t("stalls.status")}
        />
        <div style={{
          background: T.bg, borderRadius: 12,
          padding: "14px 16px",
          display: "flex", alignItems: "center", justifyContent: "space-between",
          marginBottom: 24,
        }}>
          <div>
            <div style={{ fontWeight: 700, fontSize: 14, color: T.textDark }}>{t("stalls.stallStatus")}</div>
            <div style={{ fontSize: 12, color: T.textMuted, marginTop: 2, maxWidth: 230 }}>
              {t("stalls.stallStatusHint")}
            </div>
          </div>
          <Form.Item name="is_open" valuePropName="checked" noStyle>
            <Switch />
          </Form.Item>
        </div>

        <div style={{ borderTop: "1px solid #F3F4F6", marginBottom: 20 }} />

        {/* ── DISPLAY ORDER ─────────────────────────── */}
        <SectionHeader
          icon={<span style={{ fontSize: 16, background: T.surfaceBlue, borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center" }}>☰</span>}
          label={t("stalls.displayOrder")}
        />
        <Form.Item name="sort_order" style={{ marginBottom: 4 }}>
          <InputNumber
            min={0}
            style={{ width: 120, borderRadius: 10, height: 44 }}
          />
        </Form.Item>
        <div style={{ fontSize: 12, color: T.textMuted, marginBottom: 24 }}>
          {t("stalls.displayOrderHint")}
        </div>

        <div style={{ borderTop: "1px solid #F3F4F6", marginBottom: 20 }} />

        {/* ── OPENING HOURS ─────────────────────────── */}
        <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: T.textDark, textTransform: "uppercase", marginBottom: 14 }}>
          {t("stalls.openingHours")}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
          <span style={{ fontWeight: 600, fontSize: 14, color: T.textDark }}>{t("stalls.weekdaysHours")}</span>
          <span style={{ fontSize: 14, color: T.textBody }}>{t("stalls.hoursWeekdayExample")}</span>
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 28 }}>
          <span style={{ fontWeight: 600, fontSize: 14, color: T.textDark }}>{t("stalls.weekendHours")}</span>
          <span style={{ fontSize: 14, color: T.textBody }}>{t("stalls.hoursWeekendExample")}</span>
        </div>

        {/* ── FOOTER BUTTONS ────────────────────────── */}
        <div style={{ display: "flex", gap: 12 }}>
          <Button
            onClick={handleDiscard}
            style={{ flex: 1, height: 48, borderRadius: 24, fontWeight: 700, fontSize: 14, border: "1px solid #E5E7EB", color: T.textDark }}
          >
            {t("stalls.discard")}
          </Button>
          <Button
            type="primary"
            htmlType="submit"
            loading={createStall.isPending}
            style={{ flex: 1.5, height: 48, borderRadius: 24, fontWeight: 700, fontSize: 14, background: T.brand, border: "none" }}
          >
            {t("stalls.createStall")}
          </Button>
        </div>
      </Form>
    </Drawer>
  );
}

// ─── Main screen ─────────────────────────────────────────────────────────────

export function StallsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [addOpen, setAddOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [editing, setEditing] = useState<Stall | null>(null);
  const [editForm] = Form.useForm<Partial<Stall>>();

  const { data, isLoading } = useAdminStalls();
  const updateStall = useUpdateStall();

  const openEdit = (s: Stall) => {
    setEditing(s);
    editForm.setFieldsValue({
      name: s.name,
      description: s.description,
      sort_order: s.sort_order,
      cover_image: s.cover_image,
      is_open: s.is_open,
    });
    setEditOpen(true);
  };

  const onSave = async (values: Partial<Stall>) => {
    if (!editing) return;
    try {
      await updateStall.mutateAsync({ id: editing.id, ...values });
      void message.success(t("stalls.updateSuccess"));
      setEditOpen(false);
    } catch {
      void message.error(t("stalls.saveFailed"));
    }
  };

  const toggleOpen = async (row: Stall, next: boolean) => {
    try {
      await updateStall.mutateAsync({ id: row.id, is_open: next });
      void message.success(next ? t("stalls.opened") : t("stalls.closed"));
    } catch {
      void message.error(t("stalls.saveFailed"));
    }
  };

  const columns: ColumnsType<Stall> = [
    {
      title: t("stalls.colCover"), dataIndex: "cover_image", key: "cover", width: 80,
      render: (v?: string | null) => v
        ? <img src={v} alt="" style={{ width: 56, height: 40, objectFit: "cover", borderRadius: 6 }} />
        : <span style={{ color: "#9CA3AF" }}>—</span>,
    },
    { title: t("stalls.colName"), dataIndex: "name", key: "name" },
    {
      title: t("stalls.colDescription"), dataIndex: "description", key: "description",
      render: (v?: string | null) => v ?? <span style={{ color: "#9CA3AF" }}>—</span>,
    },
    {
      title: t("stalls.colSortOrder"), dataIndex: "sort_order", key: "sort_order", width: 70,
      render: (v: number) => <Tag>{v}</Tag>,
    },
    {
      title: t("stalls.colOpen"), dataIndex: "is_open", key: "is_open", width: 100,
      render: (v: boolean, row) => (
        <Switch checked={v} onChange={(checked) => void toggleOpen(row, checked)} size="small" />
      ),
    },
    {
      title: "", key: "actions", width: 60, fixed: "right",
      render: (_, row) => (
        <Tooltip title={t("stalls.tooltipEdit")}>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
        </Tooltip>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px 40px", background: T.bg, minHeight: "100vh" }}>
        <div style={{ maxWidth: 1480, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", gap: 18, marginBottom: 22, flexWrap: "wrap" }}>
            <div>
              <div style={{ display: "inline-flex", alignItems: "center", padding: "6px 12px", borderRadius: 999, background: T.brandLight, color: T.brand, fontSize: 11, fontWeight: 900, textTransform: "uppercase", marginBottom: 10 }}>
                {(data?.data ?? []).length.toLocaleString()}
              </div>
              <h1 style={{ margin: 0, fontSize: 32, lineHeight: 1.1, fontWeight: 900, color: T.textDark }}>{t("stalls.title")}</h1>
            </div>
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={() => setAddOpen(true)}
              style={{ background: T.brand, border: "none", borderRadius: 12, fontWeight: 800, height: 44, paddingInline: 20, boxShadow: "0 12px 24px rgba(249,115,22,0.18)" }}
            >
              {t("stalls.addStall")}
            </Button>
          </div>

          <div style={{ background: T.surface, borderRadius: 16, border: "1px solid #E5E7EB", overflow: "hidden", boxShadow: "0 14px 34px rgba(15,23,42,0.05)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #F3F4F6" }}>
              <div style={{ fontSize: 16, fontWeight: 900, color: T.textDark }}>{t("stalls.title")}</div>
              <div style={{ fontSize: 12, fontWeight: 700, color: T.textMuted }}>{(data?.data ?? []).length.toLocaleString()}</div>
            </div>
            <DataTable<Stall> columns={columns} dataSource={data?.data ?? []} loading={isLoading} />
          </div>
        </div>
      </div>

      {/* Add Stall Drawer */}
      <AddStallModal open={addOpen} onClose={() => setAddOpen(false)} />

      {/* Edit Stall Modal */}
      <Modal
        open={editOpen}
        title={`${t("stalls.editTitle")} — ${editing?.name ?? ""}`}
        onCancel={() => setEditOpen(false)}
        onOk={() => void editForm.submit()}
        okButtonProps={{ style: { background: T.brand, borderColor: T.brand }, loading: updateStall.isPending }}
      >
        <Form form={editForm} layout="vertical" onFinish={onSave}>
          <Form.Item name="name" label={t("stalls.formName")} rules={[{ required: true, max: 120 }]}>
            <Input maxLength={120} />
          </Form.Item>
          <Form.Item name="description" label={t("stalls.formDescription")}>
            <Input.TextArea maxLength={400} rows={3} showCount />
          </Form.Item>
          <Form.Item name="cover_image" label={t("stalls.formCoverImage")}>
            <Input placeholder={t("stalls.coverUrlPlaceholder")} maxLength={500} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("stalls.formSortOrder")}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="is_open" label={t("stalls.formIsOpen")} valuePropName="checked">
            <Switch />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
