// @ts-nocheck
import { Switch, Typography, Card, Table, App, Spin } from "../components/admin-ui";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "../components/admin-ui";
import { useFeatureFlags, useToggleFlag } from "../api/hooks";
import { AdminShell } from "../layouts/AdminShell";

const { Title, Text } = Typography;

interface Flag { id: string; key: string; enabled: boolean; note: string | null }

export function FeatureFlagsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const { data, isLoading } = useFeatureFlags();
  const toggle = useToggleFlag();

  const onChange = async (key: string, enabled: boolean) => {
    try {
      await toggle.mutateAsync({ key, enabled });
      void message.success(enabled ? t("featureFlags.flagEnabled", { key }) : t("featureFlags.flagDisabled", { key }));
    } catch {
      void message.error(t("featureFlags.updateFailed"));
    }
  };

  const columns: ColumnsType<Flag> = [
    {
      title: t("featureFlags.colFlagKey"), dataIndex: "key", key: "key", width: 240,
      render: (v) => <Text code>{v}</Text>,
    },
    {
      title: t("featureFlags.colDescription"), dataIndex: "note", key: "desc",
      render: (_v, row) => {
        const localized = t(`featureFlags.desc_${row.key}`, { defaultValue: "" });
        const label = localized || row.note;
        return label ? label : <Text type="secondary">{t("featureFlags.noDescription")}</Text>;
      },
    },
    {
      title: t("featureFlags.colEnabled"), dataIndex: "enabled", key: "enabled", width: 100, align: "center",
      render: (v: boolean, row) => (
        <Switch
          checked={v}
          loading={toggle.isPending}
          onChange={(checked) => void onChange(row.key, checked)}
          checkedChildren="ON"
          unCheckedChildren="OFF"
        />
      ),
    },
  ];

  return (
    <AdminShell>
      <div className="min-h-screen bg-[#f8f9fa] px-8 pb-10 pt-7">
        <div className="mx-auto">
          <div className="mb-[22px]">
            <div className="mb-2.5 inline-flex items-center rounded-full bg-[#ffedd5] px-3 py-1.5 text-[11px] font-black uppercase text-[#ea580c]">
              {(data?.data ?? []).length.toLocaleString()}
            </div>
            <h1 className="m-0 text-[32px] font-black leading-[1.1] text-[#191c1d]">{t("featureFlags.title")}</h1>
          </div>
          <Card className="overflow-hidden rounded-2xl border border-[#e5e7eb] shadow-[0_14px_34px_rgba(15,23,42,0.05)]">
            {isLoading ? (
              <div className="p-10 text-center"><Spin /></div>
            ) : (
              <Table<Flag>
                columns={columns}
                dataSource={data?.data ?? []}
                rowKey="key"
                size="middle"
              />
            )}
          </Card>
        </div>
      </div>
    </AdminShell>
  );
}
