type AnyRecord = Record<string, any>;

export type ColumnsType<T = AnyRecord> = Array<{
  title?: ReactNode;
  dataIndex?: string | string[];
  key?: string;
  width?: number | string;
  fixed?: string;
  render?: (value: any, record: T, index: number) => ReactNode;
  [key: string]: any;
}>;

export type TableProps<T = AnyRecord> = {
  dataSource?: T[];
  columns?: ColumnsType<T>;
  rowKey?: string | ((record: T) => string);
  loading?: boolean;
  pagination?: false | AnyRecord;
  size?: string;
  scroll?: AnyRecord;
  rowClassName?: string | ((record: T, index: number) => string);
  onRow?: (record: T, index?: number) => React.HTMLAttributes<HTMLTableRowElement>;
  components?: AnyRecord;
  style?: CSSProperties;
  sticky?: any;
  footer?: any;
  [key: string]: any;
};

export type MenuProps = { items?: Array<{ key: string; label?: ReactNode; icon?: ReactNode; danger?: boolean; disabled?: boolean; onClick?: () => void; [key: string]: any }> };
export type RangePickerProps = AnyRecord;
export type Color = { toHexString?: () => string } | string;

