function cx(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

function getValue(record: AnyRecord, dataIndex: string | string[] | undefined) {
  if (!dataIndex) return undefined;
  const path = Array.isArray(dataIndex) ? dataIndex : [dataIndex];
  return path.reduce<any>((value, key) => value?.[key], record);
}

export function Table<T extends AnyRecord>(props: TableProps<T>) {
  const { t } = useTranslation();
  const { dataSource = [], columns = [], rowKey = "id", loading, rowClassName, onRow, style, pagination } = props;
  const [internalPage, setInternalPage] = useState(1);
  const wrapRef = useRef<HTMLDivElement>(null);
  const [scrollState, setScrollState] = useState<{ overflow: boolean; atEnd: boolean }>({ overflow: false, atEnd: true });
  const keyFor = (row: T, index: number) => typeof rowKey === "function" ? rowKey(row) : String(row[rowKey] ?? index);
  const paginationConfig = pagination === false ? null : (pagination ?? {});
  const controlledPage = paginationConfig?.current ? Number(paginationConfig.current) : undefined;
  const pageSize = Number(paginationConfig?.pageSize ?? paginationConfig?.defaultPageSize ?? 10);
  const total = Number(paginationConfig?.total ?? dataSource.length);
  const totalPages = Math.max(1, Math.ceil(total / Math.max(1, pageSize)));
  const currentPage = Math.min(totalPages, Math.max(1, controlledPage ?? internalPage));
  const isServerPaginated = paginationConfig?.total != null || paginationConfig?.current != null;
  const offset = paginationConfig ? (currentPage - 1) * pageSize : 0;
  const pageRows = paginationConfig
    ? isServerPaginated
      ? dataSource
      : dataSource.slice(offset, offset + pageSize)
    : dataSource;
  const isEmpty = dataSource.length === 0 && !loading;
  const rangeStart = total === 0 ? 0 : offset + 1;
  const rangeEnd = Math.min(total, offset + pageRows.length);

  useEffect(() => {
    if (!controlledPage && internalPage > totalPages) setInternalPage(totalPages);
  }, [controlledPage, internalPage, totalPages]);

  // Detect horizontal overflow so we can show a visible "more columns this
  // way" affordance — a plain `overflow-x-auto` wrapper is scrollable but
  // gives zero visual hint on mobile, so clipped columns (e.g. an Enabled
  // switch) go completely undiscovered without this.
  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const update = () => {
      const overflow = el.scrollWidth > el.clientWidth + 1;
      const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 1;
      setScrollState({ overflow, atEnd });
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => {
      el.removeEventListener("scroll", update);
      ro.disconnect();
    };
  }, [dataSource, columns, isEmpty]);

  const goToPage = (page: number) => {
    const next = Math.min(totalPages, Math.max(1, page));
    if (!controlledPage) setInternalPage(next);
    paginationConfig?.onChange?.(next, pageSize);
  };

  const pageNumbers = useMemo(() => {
    if (totalPages <= 7) return Array.from({ length: totalPages }, (_, index) => index + 1);
    const pages = new Set([1, totalPages, currentPage, currentPage - 1, currentPage + 1]);
    return Array.from(pages).filter((page) => page >= 1 && page <= totalPages).sort((a, b) => a - b);
  }, [currentPage, totalPages]);

  const showScrollHint = scrollState.overflow && !scrollState.atEnd;

  return (
    <div style={style}>
      <div className="relative">
        <div ref={wrapRef} className={cx(UI.tableWrap, isEmpty && "overflow-x-hidden")}>
        {loading ? <Spin /> : null}
        <table className={cx(UI.table, isEmpty && "min-w-full")}>
          <thead>
            <tr>{columns.map((col, i) => <th key={col.key ?? String(col.dataIndex ?? i)} style={{ width: col.width }}>{col.title}</th>)}</tr>
          </thead>
          <tbody>
            {isEmpty ? (
              <tr><td colSpan={columns.length || 1} className="!text-center px-7 py-7 text-slate-500">{t("common.noData")}</td></tr>
            ) : pageRows.map((row, rowIndex) => {
              const absoluteIndex = isServerPaginated ? rowIndex : rowIndex + offset;
              const rowProps = onRow?.(row, absoluteIndex) ?? {};
              const className = typeof rowClassName === "function" ? rowClassName(row, absoluteIndex) : rowClassName;
              return (
                <tr key={keyFor(row, absoluteIndex)} {...rowProps} className={className}>
                  {columns.map((col, colIndex) => {
                    const value = getValue(row, col.dataIndex);
                    return <td key={col.key ?? String(col.dataIndex ?? colIndex)}>{col.render ? col.render(value, row, absoluteIndex) : value}</td>;
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
        </div>
        {showScrollHint && (
          <>
            <div className="pointer-events-none absolute bottom-0 right-0 top-0 w-10 bg-gradient-to-l from-white to-transparent" aria-hidden="true" />
            <div className="pointer-events-none absolute bottom-1.5 right-2 flex items-center gap-1 rounded-full bg-[#191c1d]/80 px-2 py-0.5 text-[10px] font-black text-white">
              {t("common.swipeForMore", "Swipe →")}
            </div>
          </>
        )}
      </div>
      {paginationConfig && totalPages > 1 ? (
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-orange-100 bg-white px-4 py-3 shadow-[0_10px_24px_rgba(15,23,42,0.05)]">
          <span className="text-xs font-extrabold text-slate-500">
            {typeof paginationConfig.showTotal === "function"
              ? paginationConfig.showTotal(total, [rangeStart, rangeEnd])
              : `显示 ${rangeStart}-${rangeEnd} / ${total}`}
          </span>
          <div className="flex flex-wrap items-center gap-2">
            <button type="button" className="inline-flex h-9 min-w-9 items-center justify-center rounded-xl border border-orange-100 bg-white px-3 text-xs font-black text-[#534434] transition hover:border-orange-200 hover:bg-orange-50 disabled:cursor-not-allowed disabled:opacity-40" disabled={currentPage <= 1} onClick={() => goToPage(currentPage - 1)}>上一页</button>
            {pageNumbers.map((page, index) => (
              <React.Fragment key={page}>
                {index > 0 && page - (pageNumbers[index - 1] ?? page) > 1 ? <span className="px-1 text-xs font-black text-slate-400">...</span> : null}
                <button
                  type="button"
                  className={cx(
                    "inline-flex h-9 min-w-9 items-center justify-center rounded-xl border px-3 text-xs font-black transition",
                    page === currentPage
                      ? "!border-orange-500 !bg-orange-500 !text-white shadow-[0_8px_18px_rgba(249,115,22,0.24)] hover:!border-orange-500 hover:!bg-orange-500 hover:!text-white"
                      : "border-orange-100 bg-white text-[#534434] hover:border-orange-200 hover:bg-orange-50",
                  )}
                  onClick={() => goToPage(page)}
                >
                  {page}
                </button>
              </React.Fragment>
            ))}
            <button type="button" className="inline-flex h-9 min-w-9 items-center justify-center rounded-xl border border-orange-100 bg-white px-3 text-xs font-black text-[#534434] transition hover:border-orange-200 hover:bg-orange-50 disabled:cursor-not-allowed disabled:opacity-40" disabled={currentPage >= totalPages} onClick={() => goToPage(currentPage + 1)}>下一页</button>
          </div>
        </div>
      ) : null}
    </div>
  );
}

export function Button({ children, type, danger, loading, icon, block, style, disabled, htmlType, className = "", ...rest }: any) {
  const iconOnly = !!icon && !children;
  return (
    <button
      {...rest}
      type={htmlType ?? "button"}
      disabled={disabled || loading}
      className={cx(
        UI.button,
        type === "primary" && "border-transparent !bg-[#f97316] !text-white shadow-[0_10px_22px_rgba(249,115,22,0.22)] hover:border-transparent hover:!bg-[#ea580c] hover:!text-white",
        danger && "border-transparent !bg-[#dc2626] !text-white shadow-[0_10px_22px_rgba(220,38,38,0.18)] hover:border-transparent hover:!bg-[#b91c1c] hover:!text-white",
        block && "w-full",
        iconOnly && "size-9 min-h-9 min-w-9 p-0 leading-none [&>svg]:block [&>svg]:shrink-0",
        className,
      )}
      style={style}
    >
      {loading ? "..." : icon}{children}
    </button>
  );
}

function BaseInput({ prefix, suffix, style, value, onChange, allowClear, addonBefore, addonAfter, ...rest }: any) {
  return (
    <span className={UI.inputWrap} style={style}>
      {addonBefore}
      {prefix}
      <input {...rest} value={value ?? ""} onChange={onChange} className={UI.input} />
      {suffix}
      {addonAfter}
    </span>
  );
}

export const Input: any = Object.assign(BaseInput, {
  Password: (props: any) => <BaseInput {...props} type="password" />,
  TextArea: ({ style, value, onChange, rows = 4, showCount, allowClear, autoSize, ...rest }: any) => <textarea {...rest} rows={rows} value={value ?? ""} onChange={onChange} className={UI.textarea} style={style} />,
  Search: (props: any) => <BaseInput {...props} type="search" />,
});

export function InputNumber({ value, onChange, style, prefix, ...rest }: any) {
  return (
    <span className={UI.inputWrap} style={style}>
      {prefix && <span className="shrink-0 text-sm font-extrabold text-[#6b7280]">{prefix}</span>}
      <input {...rest} type="number" value={value ?? ""} onChange={(e) => onChange?.(e.target.value === "" ? null : Number(e.target.value))} className={UI.input} />
    </span>
  );
}

export function Select({ value, onChange, options, children, style, placeholder, allowClear, mode, className = "", ...rest }: any) {
  const childOptions = React.Children.toArray(children).map((child: any) => child?.props).filter(Boolean);
  const allOptions = options ?? childOptions;

  if (mode === "multiple") {
    return (
      <MultiSelect
        value={value} onChange={onChange} options={allOptions}
        style={style} placeholder={placeholder} allowClear={allowClear} className={className}
      />
    );
  }

  return (
    <span className={cx("relative inline-flex min-h-11 w-full items-center rounded-xl border border-[#e7e1db] bg-white shadow-[0_8px_20px_rgba(25,28,29,0.04)] transition focus-within:border-[#ea580c] focus-within:ring-4 focus-within:ring-[#ea580c]/10", className)} style={style}>
      <select {...rest} value={value ?? ""} onChange={(e) => onChange?.(e.target.value || undefined)} className="h-11 w-full cursor-pointer appearance-none rounded-xl border-0 bg-transparent py-0 pl-3.5 pr-10 text-sm font-bold text-[#191c1d] outline-none disabled:cursor-not-allowed disabled:bg-[#f3f4f5] disabled:text-[#867461]">
        {(placeholder || allowClear) && <option value="">{placeholder ?? "全部"}</option>}
        {allOptions?.map((option: any) => <option key={option.value} value={option.value} disabled={option.disabled}>{option.label ?? option.children}</option>)}
      </select>
      <svg className="pointer-events-none absolute right-3.5 top-1/2 size-4 -translate-y-1/2 text-[#a14000]" viewBox="0 0 20 20" fill="none" aria-hidden="true">
        <path d="M5 7.5L10 12.5L15 7.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </span>
  );
}
Select.Option = ({ children }: any) => <>{children}</>;

// mode="multiple" needs real array semantics — a native <select> can only ever
// carry one scalar value, so it silently dropped every selection beyond the
// first (and React warned about passing an array where a scalar was expected).
// This renders a checklist popover instead and always calls onChange with an array.
function MultiSelect({ value, onChange, options, style, placeholder, allowClear, className = "" }: any) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const popoverRef = useRef<HTMLDivElement>(null);
  const [popoverStyle, setPopoverStyle] = useState<CSSProperties>({});
  const selected: string[] = Array.isArray(value) ? value : [];

  const updatePopoverPosition = () => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    setPopoverStyle({ position: "fixed", top: rect.bottom + 4, left: rect.left, width: rect.width, zIndex: 3000 });
  };

  // Rendered via a portal (like Modal/Drawer/Dropdown above) and positioned
  // from the trigger's getBoundingClientRect — a plain `position: absolute`
  // popover gets clipped when the trigger sits near the bottom of a
  // scrollable ancestor (e.g. a Modal body with overflow-y: auto).
  useEffect(() => {
    if (!open) return;
    updatePopoverPosition();
    const onDocClick = (e: MouseEvent) => {
      if (ref.current?.contains(e.target as Node) || popoverRef.current?.contains(e.target as Node)) return;
      setOpen(false);
    };
    const close = () => setOpen(false);
    document.addEventListener("mousedown", onDocClick);
    window.addEventListener("resize", updatePopoverPosition);
    window.addEventListener("scroll", close, true);
    return () => {
      document.removeEventListener("mousedown", onDocClick);
      window.removeEventListener("resize", updatePopoverPosition);
      window.removeEventListener("scroll", close, true);
    };
  }, [open]);

  const toggle = (val: string) => {
    const next = selected.includes(val) ? selected.filter((v) => v !== val) : [...selected, val];
    onChange?.(next);
  };
  const selectedLabels = options.filter((o: any) => selected.includes(o.value)).map((o: any) => o.label ?? o.children);

  return (
    <div ref={ref} className={cx("relative w-full", className)} style={style}>
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="flex min-h-11 w-full cursor-pointer flex-wrap items-center gap-1.5 rounded-xl border border-[#e7e1db] bg-white px-3.5 py-2 text-left text-sm font-bold text-[#191c1d] shadow-[0_8px_20px_rgba(25,28,29,0.04)] transition focus:border-[#ea580c] focus:ring-4 focus:ring-[#ea580c]/10"
      >
        {selectedLabels.length === 0 ? (
          <span className="text-[#867461]">{placeholder ?? "请选择"}</span>
        ) : (
          selectedLabels.map((label: ReactNode, i: number) => (
            <span key={i} className="inline-flex items-center rounded-md bg-[#fff7ed] px-2 py-0.5 text-xs font-bold text-[#c2410c]">{label}</span>
          ))
        )}
        {allowClear && selected.length > 0 && (
          <span
            role="button"
            onClick={(e) => { e.stopPropagation(); onChange?.([]); }}
            className="ml-auto cursor-pointer text-[#867461] hover:text-[#191c1d]"
          >
            ✕
          </span>
        )}
      </button>
      {open && createPortal(
        <div ref={popoverRef} className="max-h-64 overflow-y-auto rounded-xl border border-[#e7e1db] bg-white p-1.5 shadow-[0_16px_40px_rgba(25,28,29,0.12)]" style={popoverStyle}>
          {options.length === 0 ? (
            <div className="px-3 py-2 text-xs text-[#867461]">暂无选项</div>
          ) : (
            options.map((option: any) => (
              <label key={option.value} className="flex cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-sm font-bold text-[#191c1d] hover:bg-[#fff7ed]">
                <input
                  type="checkbox"
                  className="size-4 accent-[#f97316]"
                  checked={selected.includes(option.value)}
                  disabled={option.disabled}
                  onChange={() => toggle(option.value)}
                />
                {option.label ?? option.children}
              </label>
            ))
          )}
        </div>,
        document.body,
      )}
    </div>
  );
}

export function Switch({ checked, onChange, disabled, style }: any) {
  return <button type="button" disabled={disabled} onClick={() => onChange?.(!checked)} className={cx("h-6 w-[42px] cursor-pointer rounded-full border-0 bg-[#cbd5e1] p-[3px] disabled:cursor-not-allowed disabled:opacity-60", checked && "bg-[#f97316]")} style={style}><span className={cx("block size-[18px] rounded-full bg-white transition-transform duration-[180ms]", checked && "translate-x-[18px]")} /></button>;
}

export function Checkbox({ checked, onChange, children, style, className = "" }: any) {
  return <label className={cx("inline-flex cursor-pointer items-center gap-2 text-sm font-bold text-[#191c1d]", className)} style={style}><input type="checkbox" className="size-4 accent-[#f97316]" checked={!!checked} onChange={(e) => onChange?.(e)} />{children}</label>;
}

export function DatePicker({ value, onChange, style, placeholder, className = "" }: any) {
  const formatted = value?.format?.("YYYY-MM-DD") ?? value ?? "";
  return <input type="date" value={formatted} onChange={(e) => onChange?.(e.target.value ? dayjs(e.target.value) : null)} className={cx(UI.dateInput, className)} style={style} placeholder={placeholder} />;
}
DatePicker.RangePicker = ({ value, onChange, style, className = "" }: any) => {
  const formatted = Array.isArray(value) ? (value[0]?.format?.("YYYY-MM-DD") ?? value[0] ?? "") : "";
  return <input type="date" value={formatted} onChange={(e) => { const dates = [e.target.value, e.target.value]; onChange?.(dates, dates); }} className={cx(UI.dateInput, className)} style={style} />;
};

export function TimePicker({ value, onChange, style }: any) {
  const v = typeof value === "string" ? dayjs(value, "HH:mm") : value;
  const formatted = v?.isValid?.() ? v.format("HH:mm") : "";
  return (
    <input
      type="time"
      value={formatted}
      onChange={(e) => onChange?.(e.target.value ? dayjs(e.target.value, "HH:mm") : null)}
      className={UI.dateInput}
      style={style}
    />
  );
}

export function Card({ children, title, extra, loading, style, styles, className = "" }: any) {
  return (
    <section className={cx("overflow-hidden rounded-2xl border border-[#e5e7eb] bg-white shadow-[0_8px_22px_rgba(15,23,42,0.05)]", className)} style={style}>
      {(title || extra) && (
        <div className="flex items-center justify-between border-b border-[#e5e7eb] px-[18px] py-3.5 text-sm font-extrabold text-[#191c1d]" style={styles?.header}>
          <span>{title}</span>
          {extra}
        </div>
      )}
      <div className="p-[18px]" style={styles?.body}>{loading ? <Spin /> : children}</div>
    </section>
  );
}

export function Spin({ size }: any) {
  return <span className={cx("inline-block size-[22px] rounded-full border-[3px] border-[#fed7aa] border-t-[#f97316] animate-spin", size === "large" && "size-9")} />;
}

export function Divider({ style }: any) {
  return <div className="my-4 h-px w-full bg-[#e5e7eb]" style={style} />;
}

export function Modal({ open, visible, title, children, onCancel, onOk, footer, okText = "确定", cancelText = "取消", width, confirmLoading, okButtonProps, cancelButtonProps, maskClosable = true }: any) {
  if (!(open ?? visible)) return null;
  const node = (
    <div className={UI.modalMask} onClick={() => { if (maskClosable) onCancel?.(); }}>
      <div className={UI.modalPanel} style={{ width }} onClick={(e) => e.stopPropagation()}>
        {title && <div>{title}</div>}
        <div className="min-h-0 overflow-y-auto pr-1">{children}</div>
        {footer !== null && <div className={UI.modalFooter}>{footer ?? <><Button onClick={onCancel} {...cancelButtonProps}>{cancelText}</Button><Button type="primary" loading={confirmLoading} onClick={onOk} {...okButtonProps}>{okText}</Button></>}</div>}
      </div>
    </div>
  );
  return typeof document === "undefined" ? node : createPortal(node, document.body);
}

Modal.confirm = ({ title, content, onOk, okText, cancelText, danger }: any) => {
  void pushConfirm({ title: title ?? "", description: content, confirmLabel: okText, cancelLabel: cancelText, danger: danger ?? true }).then((ok) => {
    if (ok) void onOk?.();
  });
};

export function Drawer({ open, visible, title, extra, children, onClose, width, footer, placement, afterOpenChange, maskClosable = true }: any) {
  const isOpen = !!(open ?? visible);
  useEffect(() => {
    afterOpenChange?.(isOpen);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);
  if (!isOpen) return null;
  const node = (
    <div className={UI.modalMask} onClick={() => { if (maskClosable) onClose?.(); }}>
      <aside className={UI.drawer} data-placement={placement} style={{ width }} onClick={(e) => e.stopPropagation()}>
        {(title || extra) && (
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <div>{title}</div>
            {extra}
          </div>
        )}
        <div className="min-h-0 flex-1 overflow-y-auto">{children}</div>
        {footer && <div className={UI.modalFooter}>{footer}</div>}
      </aside>
    </div>
  );
  return typeof document === "undefined" ? node : createPortal(node, document.body);
}

export function Dropdown({ children, menu }: any) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLSpanElement | null>(null);
  const popoverRef = useRef<HTMLDivElement | null>(null);
  const [menuPosition, setMenuPosition] = useState<CSSProperties>({});
  const items = menu?.items ?? [];

  const updateMenuPosition = () => {
    const rect = triggerRef.current?.getBoundingClientRect();
    if (!rect) return;
    setMenuPosition({
      position: "fixed",
      top: rect.bottom + 8,
      right: Math.max(12, window.innerWidth - rect.right),
      zIndex: 3000,
    });
  };

  // Close-on-outside-click is done via a `mousedown` + explicit contains()
  // check (same pattern as MultiSelect above) rather than a bubble-phase
  // `window` click listener that depends on the popover/item calling
  // e.stopPropagation() to avoid self-closing. That dependency is fragile —
  // since the popover is rendered through a portal, a native click on an
  // item only reaches this listener if every intermediate handler correctly
  // stops propagation, and any gap there silently swallows the item's own
  // onClick along with the close. mousedown+contains() never has that failure
  // mode: it explicitly ignores clicks that originate inside the trigger or
  // the popover, so an item's click always gets to fire before anything closes it.
  useEffect(() => {
    if (!open) return;

    updateMenuPosition();
    const onDocMouseDown = (e: MouseEvent) => {
      const target = e.target as Node;
      if (triggerRef.current?.contains(target) || popoverRef.current?.contains(target)) return;
      setOpen(false);
    };
    const close = () => setOpen(false);
    document.addEventListener("mousedown", onDocMouseDown);
    window.addEventListener("resize", updateMenuPosition);
    window.addEventListener("scroll", close, true);

    return () => {
      document.removeEventListener("mousedown", onDocMouseDown);
      window.removeEventListener("resize", updateMenuPosition);
      window.removeEventListener("scroll", close, true);
    };
  }, [open]);

  // Focus never reached the popover via Tab because it's teleported (via
  // portal) to the very end of <body>, far from the trigger in DOM order —
  // Tab would walk through every other focusable element on the page first.
  // Moving focus into the menu on open (and trapping Tab within it while
  // open) keeps keyboard use working regardless of DOM position.
  useEffect(() => {
    if (!open) return;
    const firstItem = popoverRef.current?.querySelector<HTMLButtonElement>("button:not(:disabled)");
    firstItem?.focus();
  }, [open]);

  const closeAndRefocus = () => {
    setOpen(false);
    triggerRef.current?.querySelector<HTMLElement>("button, [tabindex]")?.focus();
  };

  const handleMenuKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const focusable = Array.from(popoverRef.current?.querySelectorAll<HTMLButtonElement>("button:not(:disabled)") ?? []);
    const currentIndex = focusable.indexOf(document.activeElement as HTMLButtonElement);
    if (e.key === "Escape") {
      e.preventDefault();
      closeAndRefocus();
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      focusable[(currentIndex + 1) % focusable.length]?.focus();
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      focusable[(currentIndex - 1 + focusable.length) % focusable.length]?.focus();
    } else if (e.key === "Tab") {
      // Trap focus inside the popover while it's open instead of letting Tab
      // escape to unrelated controls elsewhere on the page.
      e.preventDefault();
      const nextIndex = e.shiftKey
        ? (currentIndex - 1 + focusable.length) % focusable.length
        : (currentIndex + 1) % focusable.length;
      focusable[nextIndex]?.focus();
    }
  };

  return (
    <span ref={triggerRef} className="relative inline-flex">
      <span onClick={(e) => { e.stopPropagation(); updateMenuPosition(); setOpen((v) => !v); }}>{children}</span>
      {open && createPortal(
        <div
          ref={popoverRef}
          className="absolute right-0 top-[calc(100%+6px)] z-[500] min-w-40 rounded-xl border border-[#e5e7eb] bg-white p-1.5 shadow-[0_12px_28px_rgba(15,23,42,0.14)]"
          style={menuPosition}
          onKeyDown={handleMenuKeyDown}
        >
          {items.map((item: any) => (
            <button key={item.key} className="w-full cursor-pointer rounded-[9px] border-0 bg-transparent px-2.5 py-[9px] text-left text-sm font-bold hover:bg-[#fff7ed] hover:text-[#ea580c]" disabled={item.disabled} onClick={() => { item.onClick?.(); setOpen(false); }}>
              {item.icon}{item.label}
            </button>
          ))}
        </div>,
        document.body,
      )}
    </span>
  );
}

export function Popconfirm({ children, title, onConfirm, cancelLabel, confirmLabel }: any) {
  return (
    <span
      onClick={(e) => {
        e.stopPropagation();
        void pushConfirm({ title: title ?? "确定？", cancelLabel, confirmLabel, danger: true }).then((ok) => {
          if (ok) void onConfirm?.();
        });
      }}
    >
      {children}
    </span>
  );
}

// Named preset colors (matching the Ant Design vocabulary this app's screens
// were already written against — "blue", "gold", "geekblue", etc.) each need a
// readable {bg, text} pastel pair, not the raw CSS color used as a background
// with no matching text-color change — a saturated named color like `blue`
// (#0000FF) behind unchanged dark-slate text is exactly why "可选" looked broken.
const PRESET_COLORS: Record<string, { bg: string; text: string }> = {
  red: { bg: "#fff1f0", text: "#cf1322" },
  orange: { bg: "#fff7e6", text: "#d46b08" },
  gold: { bg: "#fffbe6", text: "#d48806" },
  green: { bg: "#f6ffed", text: "#389e0d" },
  success: { bg: "#f6ffed", text: "#389e0d" },
  cyan: { bg: "#e6fffb", text: "#08979c" },
  blue: { bg: "#e6f4ff", text: "#0958d9" },
  geekblue: { bg: "#f0f5ff", text: "#1d39c4" },
  purple: { bg: "#f9f0ff", text: "#531dab" },
  magenta: { bg: "#fff0f6", text: "#c41d7f" },
  lime: { bg: "#fcffe6", text: "#7cb305" },
  default: { bg: "#f1f5f9", text: "#334155" },
};
function resolvePresetColor(color: any): { bg: string; text: string } {
  if (color && PRESET_COLORS[color]) return PRESET_COLORS[color]!;
  if (typeof color === "string" && color) return { bg: color, text: "#191c1d" };
  return PRESET_COLORS.default!;
}

export function Tag({ children, color, style, onClose, closable }: any) {
  const { bg, text } = resolvePresetColor(color);
  return <span className="inline-flex items-center gap-1.5 rounded-full px-[9px] py-[3px] text-xs font-extrabold" style={{ background: bg, color: text, ...style }}>{children}{closable && <button type="button" onClick={onClose} className="cursor-pointer border-0 bg-transparent p-0 text-sm font-black leading-none text-current">×</button>}</span>;
}

export function Tooltip({ children }: any) {
  return <>{children}</>;
}

type CollapseItem = { key: string; label?: ReactNode; extra?: ReactNode; children?: ReactNode };

export const Collapse: any = ({ items, accordion, ghost, style, children }: {
  items?: CollapseItem[];
  accordion?: boolean;
  ghost?: boolean;
  style?: CSSProperties;
  children?: ReactNode;
}) => {
  const list: CollapseItem[] = items ?? [];
  const [openKeys, setOpenKeys] = useState<string[]>([]);

  if (!items) return <div style={style}>{children}</div>;

  const toggle = (key: string) => {
    setOpenKeys((prev) => {
      const isOpen = prev.includes(key);
      if (accordion) return isOpen ? [] : [key];
      return isOpen ? prev.filter((k) => k !== key) : [...prev, key];
    });
  };

  return (
    <div style={style}>
      {list.map((item) => {
        const isOpen = openKeys.includes(item.key);
        return (
          <div
            key={item.key}
            style={{
              border: ghost ? "none" : "1px solid #E5E7EB",
              borderRadius: ghost ? 0 : 8,
              marginBottom: ghost ? 0 : 8,
              overflow: "hidden",
            }}
          >
            <div
              onClick={() => toggle(item.key)}
              style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "10px 12px", cursor: "pointer",
                background: ghost ? "transparent" : "#FAFAFA",
              }}
            >
              <div style={{ flex: 1 }}>{item.label}</div>
              {item.extra}
            </div>
            {isOpen && <div style={{ padding: "0 12px 12px" }}>{item.children}</div>}
          </div>
        );
      })}
    </div>
  );
};
Collapse.Panel = ({ children }: any) => <div>{children}</div>;

