const BADGE_STATUS_COLOR: Record<string, string> = { success: "green", error: "red", warning: "gold", processing: "blue", default: "default" };

export const Badge = ({ children, count, color, status, text }: any) => {
  // Status-dot variant (color/status + text) — used for things like an
  // application's pending/approved/rejected state, distinct from the
  // notification-count variant below.
  if (color || status || text) {
    const dotColor = resolvePresetColor(color ?? BADGE_STATUS_COLOR[status] ?? "default").text;
    return (
      <span className="inline-flex items-center gap-1.5 text-sm font-bold text-[#191c1d]">
        <span className="inline-block size-2 rounded-full" style={{ background: dotColor }} />
        {text}
      </span>
    );
  }
  return <span className="relative inline-flex">{children}{count ? <sup>{count}</sup> : null}</span>;
};
