type FormRule = AnyRecord | ((form: { getFieldValue: (name: string) => any }) => AnyRecord);

type FormInstance = {
  values: AnyRecord;
  setFieldsValue: (values: AnyRecord) => void;
  setFieldValue: (name: string, value: any) => void;
  getFieldValue: (name: string) => any;
  getFieldsValue: () => AnyRecord;
  getFieldError: (name: string) => string | undefined;
  resetFields: () => void;
  validateFields: () => Promise<AnyRecord>;
  submit: () => void;
  __subscribe?: (fn: () => void) => () => void;
  __onSubmit?: (values: AnyRecord) => void;
  __setFieldRules?: (name: string, rules: FormRule[]) => void;
};

/**
 * Evaluates one antd-style rule against a value. Supports the rule shapes
 * actually used across admin-app forms: required/message, len/min/max
 * (string length or numeric bounds when type:"number"), pattern, and
 * dependency-based validator functions (e.g. confirm-PIN matching).
 */
async function evaluateFormRule(rule: FormRule, value: any, form: FormInstance): Promise<string | undefined> {
  const resolved = typeof rule === "function" ? rule({ getFieldValue: form.getFieldValue }) : rule;
  const isEmpty = value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0);

  if (resolved.required && isEmpty) return resolved.message || "This field is required";
  if (isEmpty) return undefined; // non-required rules don't fire on an empty value

  const isNumberType = resolved.type === "number";
  if (resolved.len != null) {
    const len = isNumberType ? undefined : String(value).length;
    if (len != null && len !== resolved.len) return resolved.message || `Must be exactly ${resolved.len} characters`;
  }
  if (resolved.min != null) {
    if (isNumberType ? Number(value) < resolved.min : String(value).length < resolved.min) {
      return resolved.message || (isNumberType ? `Must be at least ${resolved.min}` : `Must be at least ${resolved.min} characters`);
    }
  }
  if (resolved.max != null) {
    if (isNumberType ? Number(value) > resolved.max : String(value).length > resolved.max) {
      return resolved.message || (isNumberType ? `Must be at most ${resolved.max}` : `Must be at most ${resolved.max} characters`);
    }
  }
  if (resolved.pattern && !resolved.pattern.test(String(value))) return resolved.message || "Invalid format";
  if (resolved.validator) {
    try {
      await resolved.validator(resolved, value);
    } catch (e) {
      return (e as Error)?.message || resolved.message || "Invalid value";
    }
  }
  return undefined;
}

function createForm(): FormInstance {
  const listeners = new Set<() => void>();
  const fieldRules = new Map<string, FormRule[]>();
  const errors: Record<string, string | undefined> = {};
  const form: FormInstance = {
    values: {},
    setFieldsValue(values) { Object.assign(form.values, values); listeners.forEach((fn) => fn()); },
    setFieldValue(name, value) { form.values[name] = value; delete errors[name]; listeners.forEach((fn) => fn()); },
    getFieldValue(name) { return form.values[name]; },
    getFieldsValue() { return { ...form.values }; },
    getFieldError(name) { return errors[name]; },
    resetFields() { form.values = {}; fieldRules.clear(); for (const k of Object.keys(errors)) delete errors[k]; listeners.forEach((fn) => fn()); },
    __setFieldRules(name, rules) { fieldRules.set(name, rules); },
    async validateFields() {
      const nextErrors: Record<string, string | undefined> = {};
      for (const [name, rules] of fieldRules.entries()) {
        for (const rule of rules) {
          const message = await evaluateFormRule(rule, form.values[name], form);
          if (message) { nextErrors[name] = message; break; }
        }
      }
      for (const k of Object.keys(errors)) delete errors[k];
      Object.assign(errors, nextErrors);
      listeners.forEach((fn) => fn());
      const firstError = Object.values(nextErrors)[0];
      if (firstError) throw new Error(firstError);
      return form.values;
    },
    async submit() {
      try {
        await form.validateFields();
      } catch {
        return; // validation failed — errors are already surfaced inline, don't call onFinish
      }
      form.__onSubmit?.(form.values);
    },
    __subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn); },
  };
  return form;
}

const FormContext = createContext<FormInstance | null>(null);

function FormRoot({ children, form, onFinish, initialValues, style }: any) {
  const actualForm = useMemo(() => form ?? createForm(), [form]);
  useMemo(() => { if (initialValues) actualForm.setFieldsValue(initialValues); actualForm.__onSubmit = onFinish; }, [actualForm, initialValues, onFinish]);
  return <FormContext.Provider value={actualForm}><form className="m-0" style={style} onSubmit={(e) => { e.preventDefault(); void actualForm.submit(); }}>{children}</form></FormContext.Provider>;
}

function FormItem({ children, name, label, extra, valuePropName = "value", style, className = "", rules }: any) {
  const form = useContext(FormContext);
  const [, force] = useState(0);
  React.useEffect(() => form?.__subscribe?.(() => force((n) => n + 1)), [form]);
  if (name && rules) form?.__setFieldRules?.(name, rules);
  const child = React.Children.only(children) as any;
  const error = name ? form?.getFieldError?.(name) : undefined;
  const injected = name ? {
    [valuePropName]: form?.getFieldValue(name),
    onChange: (...args: any[]) => {
      const first = args[0];
      const value = first?.target ? (valuePropName === "checked" ? first.target.checked : first.target.value) : first;
      form?.setFieldValue(name, value);
      child.props?.onChange?.(...args);
    },
  } : {};
  return (
    <label className={cx("mb-3.5 block", className)} style={style}>
      {label && <div className="mb-1.5 text-xs font-extrabold text-[#6b7280]">{label}</div>}
      {React.cloneElement(child, injected)}
      {error && <div className="mt-1.5 text-xs font-bold text-red-600">{error}</div>}
      {extra && <div className="mt-1.5 text-xs text-[#6b7280]">{extra}</div>}
    </label>
  );
}

function useFormHook<T extends AnyRecord>() {
  return React.useMemo(() => [createForm() as FormInstance & { __type?: T }], []);
}

function useWatchHook(name: string, formOrOptions?: FormInstance | { form?: FormInstance }) {
  const contextForm = useContext(FormContext);
  const directForm = formOrOptions && typeof (formOrOptions as FormInstance).getFieldValue === "function"
    ? formOrOptions as FormInstance
    : undefined;
  const optionsForm = formOrOptions && !directForm ? (formOrOptions as { form?: FormInstance }).form : undefined;
  const form = directForm ?? optionsForm ?? contextForm;
  const [value, setValue] = useState(() => form?.getFieldValue?.(name));

  React.useEffect(() => {
    setValue(form?.getFieldValue?.(name));
    return form?.__subscribe?.(() => setValue(form.getFieldValue(name)));
  }, [form, name]);

  return value;
}

export const Form: any = Object.assign(FormRoot, {
  Item: FormItem,
  useForm: useFormHook,
  useWatch: useWatchHook,
});

export const message = {
  success: (text: ReactNode) => pushToast(String(text), "success"),
  error: (text: ReactNode) => pushToast(String(text), "error"),
  warning: (text: ReactNode) => pushToast(String(text), "error"),
  info: (text: ReactNode) => pushToast(String(text), "info"),
};

