import { useAuthStore } from "../store/auth";

export type AdminRole = "superadmin" | "admin" | "stall_staff" | "pos_operator";

// Route-level permissions per role
const ROLE_ROUTES: Record<AdminRole, string[]> = {
  superadmin: [
    "/", "/orders", "/transactions", "/refunds", "/menu", "/categories", "/vouchers", "/bundles",
    "/stalls", "/stall-applications", "/staff", "/reports", "/activity", "/flags", "/hours", "/settings",
    "/payment-methods", "/delivery-providers", "/banners", "/pricing-rules", "/legal-content",
  ],
  admin: [
    "/", "/orders", "/transactions", "/refunds", "/menu", "/categories", "/vouchers", "/bundles",
    "/stalls", "/stall-applications", "/staff", "/reports", "/activity", "/hours",
    "/payment-methods", "/delivery-providers", "/banners", "/legal-content",
    // NOT /flags and /settings (superadmin only)
  ],
  stall_staff: [
    "/menu",       // manage their stall's menu
    "/categories", // manage their stall's categories
    "/orders",     // view orders for their stall
    "/reports",    // view stall-level reports
  ],
  pos_operator: [
    // POS operators use the POS app, not admin app
    // If they somehow land here, just show orders as read-only
    "/orders",
  ],
};

export function usePermissions() {
  const role = (useAuthStore((s) => s.staff?.role) ?? "pos_operator") as AdminRole;

  const allowedRoutes = ROLE_ROUTES[role] ?? [];

  const can = (action: string) => {
    switch (action) {
      // Feature flags + Settings — superadmin only
      case "manage:settings":
      case "manage:feature_flags":
        return role === "superadmin";
      // Staff management — superadmin + admin
      case "manage:staff":
        return role === "superadmin" || role === "admin";
      // Vouchers + Bundles — superadmin + admin
      case "manage:vouchers":
      case "manage:bundles":
        return role === "superadmin" || role === "admin";
      // Stall applications — superadmin + admin
      case "manage:stall_applications":
        return role === "superadmin" || role === "admin";
      // Refunds — superadmin + admin
      case "manage:refunds":
        return role === "superadmin" || role === "admin";
      // Menu — superadmin + admin + stall_staff
      case "manage:menu":
        return role === "superadmin" || role === "admin" || role === "stall_staff";
      // Orders — all roles
      case "view:orders":
        return true;
      // Activity log — superadmin + admin
      case "view:activity":
        return role === "superadmin" || role === "admin";
      // Delete actions — superadmin + admin
      case "delete:any":
        return role === "superadmin" || role === "admin";
      // Edit/create — superadmin + admin + stall_staff (own stall only)
      case "create:menu_item":
      case "edit:menu_item":
        return role === "superadmin" || role === "admin" || role === "stall_staff";
      default:
        return role === "superadmin";
    }
  };

  const canRoute = (path: string) => allowedRoutes.includes(path);

  const isSuperAdmin = role === "superadmin";
  const isAdmin = role === "superadmin" || role === "admin";
  const isStallStaff = role === "stall_staff";

  return { role, can, canRoute, isSuperAdmin, isAdmin, isStallStaff, allowedRoutes };
}
