import dayjs from "dayjs";
import utc from "dayjs/plugin/utc";
import timezone from "dayjs/plugin/timezone";
import type { ConfigType } from "dayjs";

dayjs.extend(utc);
dayjs.extend(timezone);

const MYT = "Asia/Kuala_Lumpur";

export function isZhLocale(lng: string): boolean {
  return lng === "zh" || lng.startsWith("zh");
}

function d(input: ConfigType) {
  return dayjs(input).tz(MYT);
}

/** Full date + time for headers and detail rows. */
export function formatDateTimeDetail(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("YYYY年M月D日 A h:mm");
  return x.format("D MMM YYYY h.mm A");
}

/** Shorter datetime for timeline sidebars. */
export function formatDateTimeCompact(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("M月D日 A h:mm");
  return x.format("D MMM h.mm A");
}

/** Date only (no time). */
export function formatDateOnly(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("YYYY年M月D日");
  return x.format("D MMM YYYY");
}

/** Order table date only. */
export function formatOrderDate(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("YYYY年M月D日");
  return x.format("D MMM YYYY");
}

/** Order table time only. */
export function formatOrderTime(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("A h:mm");
  return x.format("h.mm A");
}

/** Date + time with seconds for audit-style tables. */
export function formatDateTimeWithSeconds(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("YYYY年M月D日 A h:mm:ss");
  return x.format("D MMM YYYY h.mm:ss A");
}

/** Month + day, useful in compact ranges. */
export function formatMonthDay(input: ConfigType, lng: string): string {
  const x = d(input);
  if (isZhLocale(lng)) return x.format("M月D日");
  return x.format("D MMM");
}
