type IconProps = {
  style?: CSSProperties;
  className?: string;
};

function lucideIcon(Component: LucideIcon) {
  return function Icon({ style, className }: IconProps) {
    return (
      <Component
        aria-hidden="true"
        className={className}
        size="1em"
        strokeWidth={2.35}
        style={{
          display: "inline-block",
          flexShrink: 0,
          verticalAlign: "-0.125em",
          ...style,
        }}
      />
    );
  };
}

