// @ts-nocheck
import { useState, useMemo } from "react";
import {
  Button, Modal, Form, Input, Select, Switch, Space, Typography, Tag,
  Popconfirm, message, Tooltip, Table, Badge,
} from "../components/admin-ui";
import {
  PlusOutlined, EditOutlined, DeleteOutlined, ApiOutlined, WalletOutlined,
} from "../components/admin-icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "../components/admin-ui";
import type { PaymentMethodConfig } from "@kawkaw/shared";
import { tokens } from "../styles/tokens";
import { AdminShell } from "../layouts/AdminShell";
import {
  usePaymentMethodConfigs, useCreatePaymentMethodConfig,
  useUpdatePaymentMethodConfig, useDeletePaymentMethodConfig, useTestPaymentMethodConfig,
} from "../api/hooks";

const { Title, Text } = Typography;
const { color: T } = tokens;

const PROVIDER_COLOR: Record<string, string> = {
  billplz: "blue", toyyibpay: "green", stripe: "purple",
  manual: "default", qr_static: "orange", grabpay: "cyan",
  boost: "lime", tng: "gold", hyperswitch: "volcano", fiuu: "magenta", custom: "geekblue",
};

// Known base URLs per provider — used to auto-fill base_url when Sandbox Mode
// is toggled, so an admin never has to hand-type (or mistype) a provider's
// API host. Only providers with well-known REST endpoints are listed; others
// (billplz/toyyibpay have their sandbox/production hosts hardcoded server-side)
// fall back to manual entry.
const PROVIDER_URLS: Record<string, { sandbox: string; production: string }> = {
  hyperswitch: { sandbox: "https://sandbox.hyperswitch.io", production: "https://api.hyperswitch.io" },
  fiuu: { sandbox: "https://sandbox-payment.fiuu.com", production: "https://pay.fiuu.com" },
};

export function PaymentMethodsScreen() {
  const { t } = useTranslation();
  const providerOptions = useMemo(
    () =>
      (
        [
          ["billplz", "providerBillplz"],
          ["toyyibpay", "providerToyyibpay"],
          ["stripe", "providerStripe"],
          ["manual", "providerManual"],
          ["qr_static", "providerQrStatic"],
          ["grabpay", "providerGrabpay"],
          ["boost", "providerBoost"],
          ["tng", "providerTng"],
          ["hyperswitch", "providerHyperswitch"],
          ["fiuu", "providerFiuu"],
          ["custom", "providerCustom"],
        ] as const
      ).map(([value, key]) => ({ value, label: t(`paymentMethods.${key}`) })),
    [t],
  );
  const methodOptions = useMemo(
    () =>
      (
        [
          ["fpx", "methodFpx"],
          ["visa", "methodVisa"],
          ["grabpay", "methodGrabpay"],
          ["cash", "methodCash"],
          ["ewallet", "methodEwallet"],
          ["tng", "methodTng"],
          ["boost", "methodBoost"],
          ["qr", "methodQr"],
        ] as const
      ).map(([value, key]) => ({ value, label: t(`paymentMethods.${key}`) })),
    [t],
  );
  const providerLabel = (v: string) => providerOptions.find(p => p.value === v)?.label ?? v;
  const methodLabel = (v: string) => methodOptions.find(m => m.value === v)?.label ?? v;
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<PaymentMethodConfig | null>(null);
  const [form] = Form.useForm();

  // Auto-fill base_url from the known sandbox/production pair whenever the
  // provider or the Sandbox Mode switch changes — an admin should never have
  // to hand-type (or mistype) a gateway's API host.
  const applyKnownUrl = (provider: string | undefined, isSandbox: boolean) => {
    const known = provider ? PROVIDER_URLS[provider] : undefined;
    if (known) form.setFieldValue("base_url", isSandbox ? known.sandbox : known.production);
  };

  const { data, isLoading } = usePaymentMethodConfigs();
  const createConfig = useCreatePaymentMethodConfig();
  const updateConfig = useUpdatePaymentMethodConfig();
  const deleteConfig = useDeletePaymentMethodConfig();
  const testConfig = useTestPaymentMethodConfig();

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (row: PaymentMethodConfig) => {
    setEditing(row);
    form.setFieldsValue({ ...row });
    setModalOpen(true);
  };

  const onSave = async (values: Record<string, unknown>) => {
    try {
      if (editing) {
        await updateConfig.mutateAsync({ id: editing.id, ...values });
        void message.success(t("paymentMethods.updateSuccess"));
      } else {
        await createConfig.mutateAsync(values);
        void message.success(t("paymentMethods.createSuccess"));
      }
      setModalOpen(false);
    } catch { void message.error(t("paymentMethods.saveFailed")); }
  };

  const onDelete = async (id: string) => {
    try { await deleteConfig.mutateAsync(id); void message.success(t("paymentMethods.deleteSuccess")); }
    catch { void message.error(t("paymentMethods.deleteFailed")); }
  };

  const onTest = async (id: string) => {
    try {
      const res = await testConfig.mutateAsync(id);
      const result = (res as { data?: { success: boolean; message: string } }).data;
      if (result?.success) {
        void message.success(t("common.connectionTestOk", { message: result.message }));
      } else {
        void message.error(
          t("common.connectionTestFailed", {
            message: result?.message ?? t("transactions.testFailedGeneric"),
          }),
        );
      }
    } catch { void message.error(t("paymentMethods.testFailed")); }
  };

  const items = (data as { data?: PaymentMethodConfig[] } | undefined)?.data ?? [];

  const columns: ColumnsType<PaymentMethodConfig> = [
    {
      title: t("paymentMethods.colProvider"), dataIndex: "provider", key: "provider", width: 160,
      render: (v: string) => <Tag color={PROVIDER_COLOR[v] ?? "default"}>{providerLabel(v)}</Tag>,
    },
    {
      title: t("paymentMethods.colMethod"), dataIndex: "method", key: "method", width: 130,
      render: (v: string) => <Tag>{methodLabel(v)}</Tag>,
    },
    {
      title: t("paymentMethods.colDisplayName"), dataIndex: "display_name", key: "display_name",
      render: (v: string) => <Text strong>{v}</Text>,
    },
    {
      title: t("paymentMethods.colApiKey"), dataIndex: "api_key", key: "api_key", width: 160,
      render: (v: string | null) => v ? <Text code style={{ fontSize: 11 }}>{v}</Text> : <Text type="secondary">—</Text>,
    },
    {
      title: t("deliveryProviders.formSandboxMode", "Sandbox Mode"), dataIndex: "is_sandbox", key: "is_sandbox", width: 110,
      render: (v: boolean) => (
        <Tag color={v ? "gold" : "green"}>{v ? t("deliveryProviders.sandbox", "Sandbox") : t("deliveryProviders.production", "Production")}</Tag>
      ),
    },
    {
      title: t("paymentMethods.colQrCode"), dataIndex: "qr_image_url", key: "qr", width: 80,
      render: (v: string | null) => v ? (
        <Tooltip title={<img src={v} alt={t("paymentMethods.qrPreviewAlt")} style={{ width: 120, height: 120 }} />}>
          <Badge status="success" text={t("paymentMethods.colQrBadge")} />
        </Tooltip>
      ) : <Text type="secondary">—</Text>,
    },
    {
      title: t("paymentMethods.colStatus"), dataIndex: "is_active", key: "active", width: 90,
      render: (v: boolean) => <Tag color={v ? "success" : "default"}>{v ? t("common.yes") : t("common.no")}</Tag>,
    },
    {
      title: "", key: "actions", width: 140, fixed: "right" as const,
      render: (_: unknown, row: PaymentMethodConfig) => (
        <Space>
          <Tooltip title={t("paymentMethods.testConnection")}>
            <Button size="small" icon={<ApiOutlined />} loading={testConfig.isPending} onClick={() => void onTest(row.id)} />
          </Tooltip>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm title={t("paymentMethods.confirmDelete")} onConfirm={() => void onDelete(row.id)} okType="danger" placement="left">
            <Button size="small" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px 40px", background: T.bg, minHeight: "100vh" }}>
        <div style={{ maxWidth: 1480, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", gap: 18, marginBottom: 22, flexWrap: "wrap" }}>
            <div>
              <div style={{ display: "inline-flex", alignItems: "center", gap: 8, padding: "6px 12px", borderRadius: 999, background: T.brandLight, color: T.brand, fontSize: 11, fontWeight: 900, textTransform: "uppercase", marginBottom: 10 }}>
                <WalletOutlined /> {items.length.toLocaleString()}
              </div>
              <h1 style={{ margin: 0, fontSize: 32, lineHeight: 1.1, fontWeight: 900, color: T.textDark }}>{t("paymentMethods.title")}</h1>
              <div style={{ marginTop: 8, fontSize: 13, color: T.textMuted, fontWeight: 600 }}>{t("paymentMethods.subtitle")}</div>
            </div>
            <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
              style={{ background: T.brand, borderColor: T.brand, height: 44, borderRadius: 12, fontWeight: 800, paddingInline: 20, boxShadow: "0 12px 24px rgba(249,115,22,0.18)" }}>
              {t("paymentMethods.addMethod")}
            </Button>
          </div>

          <div style={{ background: T.surface, borderRadius: 16, border: "1px solid #E5E7EB", overflow: "hidden", boxShadow: "0 14px 34px rgba(15,23,42,0.05)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #F3F4F6" }}>
              <div style={{ fontSize: 16, fontWeight: 900, color: T.textDark }}>{t("paymentMethods.title")}</div>
              <div style={{ fontSize: 12, fontWeight: 700, color: T.textMuted }}>{items.length.toLocaleString()}</div>
            </div>
            <Table<PaymentMethodConfig>
              columns={columns}
              dataSource={items}
              rowKey="id"
              loading={isLoading}
              size="middle"
              pagination={{ pageSize: 10 }}
              scroll={{ x: 900 }}
            />
          </div>
        </div>
      </div>

      <Modal
        open={modalOpen}
        title={
          <Space>
            <WalletOutlined />
            {editing ? t("paymentMethods.editTitle") : t("paymentMethods.newTitle")}
          </Space>
        }
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okText={t("common.save")}
        okButtonProps={{ style: { background: T.brandAmber, borderColor: T.brandAmber }, loading: createConfig.isPending || updateConfig.isPending }}
        width={580}
        maskClosable={false}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="provider" label={t("paymentMethods.formProvider")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <Select options={providerOptions} placeholder={t("paymentMethods.phSelectProvider")}
                onChange={(v: string) => applyKnownUrl(v, form.getFieldValue("is_sandbox") ?? true)} />
            </Form.Item>
            <Form.Item name="method" label={t("paymentMethods.formMethod")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <Select options={methodOptions} placeholder={t("paymentMethods.phSelectMethod")} />
            </Form.Item>
          </Space>
          <Form.Item name="display_name" label={t("paymentMethods.formDisplayName")} rules={[{ required: true }]}>
            <Input placeholder={t("paymentMethods.phDisplayName")} />
          </Form.Item>
          <Form.Item name="is_sandbox" label={t("deliveryProviders.formSandboxMode", "Sandbox Mode")} valuePropName="checked" initialValue={true}
            extra={t("deliveryProviders.sandboxModeHint", "Sandbox uses the gateway's test environment — switch off only once you have real production credentials.")}>
            <Switch checkedChildren={t("deliveryProviders.sandbox", "Sandbox")} unCheckedChildren={t("deliveryProviders.production", "Production")}
              onChange={(checked: boolean) => applyKnownUrl(form.getFieldValue("provider"), checked)} />
          </Form.Item>
          <Form.Item name="api_key" label={t("paymentMethods.formApiKey")}>
            <Input.Password placeholder={t("paymentMethods.formApiKeyPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="api_secret" label={t("paymentMethods.formApiSecret")}>
            <Input.Password placeholder={t("paymentMethods.formApiSecretPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="merchant_id" label={t("paymentMethods.formMerchantId")}>
            <Input placeholder={t("paymentMethods.phMerchantId")} />
          </Form.Item>
          <Form.Item name="collection_id" label={t("paymentMethods.formCollectionId")}>
            <Input placeholder={t("paymentMethods.phCollectionId")} />
          </Form.Item>
          <Form.Item name="webhook_secret" label={t("paymentMethods.formWebhookSecret")}>
            <Input.Password placeholder={t("paymentMethods.formWebhookSecretPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="base_url" label={t("deliveryProviders.formBaseUrl")}>
            <Input placeholder={t("deliveryProviders.phBaseUrl")} />
          </Form.Item>
          <Form.Item name="qr_image_url" label={t("paymentMethods.formQrImageUrl")}>
            <Input placeholder={t("paymentMethods.phQrUrl")} />
          </Form.Item>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="sort_order" label={t("paymentMethods.formSortOrder")} initialValue={0} style={{ flex: 1 }}>
              <Input type="number" min={0} />
            </Form.Item>
            <Form.Item name="is_active" label={t("paymentMethods.formIsActive")} valuePropName="checked" initialValue={true} style={{ flex: 1 }}>
              <Switch checkedChildren={t("common.yes")} unCheckedChildren={t("common.no")} />
            </Form.Item>
          </Space>
        </Form>
      </Modal>
    </AdminShell>
  );
}
