/* ─── Period helpers ─────────────────────────────────────── */
function periodRange(period: Period): [Dayjs, Dayjs] {
  const today = dayjs();
  if (period === "today") return [today.startOf("day"), today.endOf("day")];
  if (period === "week")  return [today.subtract(6, "day").startOf("day"), today.endOf("day")];
  return [today.startOf("month"), today.endOf("day")];
}

function periodLabel(range: [Dayjs, Dayjs], lng: string): string {
  return `${formatDateOnly(range[0], lng)} – ${formatDateOnly(range[1], lng)}`;
}

