export function RefundsScreen() {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const [status, setStatus] = useState<string | undefined>();
  const [type, setType] = useState<string | undefined>();
  const [method, setMethod] = useState<string | undefined>();
  const [search, setSearch] = useState("");
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);
  const [updateTarget, setUpdateTarget] = useState<AdminRefundItem | null>(null);
  const [filterRef, filterHeight] = useElementHeight<HTMLDivElement>();

  const filterParams = useMemo(() => ({
    page, limit: 10,
    status: status || undefined,
    type: type || undefined,
    method: method || undefined,
    q: search || undefined,
    from: dateRange?.[0] || undefined,
    to: dateRange?.[1] || undefined,
  }), [page, status, type, method, search, dateRange]);

  const { data, isLoading } = useAdminRefunds(filterParams);
  const { data: stats } = useRefundStats();

  const refunds = (data?.data ?? []) as AdminRefundItem[];
  const totalCount = data?.meta.total ?? 0;

  const TH = (key: string) => (
    <span className="text-[11px] font-black uppercase tracking-[0.5px] text-[#7a6f65]">{t(key)}</span>
  );

  const payLabel = (method: string) => t(PAYMENT_I18N_KEYS[method] ?? method);

  async function exportRefundsPdf() {
    const doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
    const pageWidthMm = doc.internal.pageSize.getWidth();
    const pageHeightMm = doc.internal.pageSize.getHeight();
    const pageWidth = 1600;
    const pageHeight = 1120;
    const margin = 60;
    const dateLabel = dateRange
      ? `${formatOrderDate(dateRange[0], i18n.language)} - ${formatOrderDate(dateRange[1], i18n.language)}`
      : t("transactions.datePresetAll");
    const tableWidth = pageWidth - margin * 2;
    const colWidths = [135, 190, 210, 125, 135, 135, 170, 370];
    const typeLabelFor = (value: string) => value === "full" ? t("refunds.typeFull") : value === "partial" ? t("refunds.typePartial") : value;
    const statusLabelFor = (value: string) => value === "pending"
      ? t("refunds.statusPending")
      : value === "success"
      ? t("refunds.statusSuccess")
      : value === "rejected"
      ? t("refunds.statusRejectedPill")
      : value === "failed"
      ? t("refunds.statusFailed")
      : value;
    const rows = refunds.map((row) => ({
      refundId: refundDisplayId(row.id),
      txnId: formatTransactionId(row.transaction_id),
      orderCode: `#${row.order?.order_code ?? "-"}`,
      customer: row.order?.customer?.name ?? t("common.guest"),
      amount: `RM ${Number(row.amount).toFixed(2)}`,
      method: PAYMENT_I18N_KEYS[row.method] ? payLabel(row.method) : row.method,
      type: row.type,
      typeLabel: typeLabelFor(row.type),
      status: row.status,
      statusLabel: statusLabelFor(row.status),
      reason: row.reason ?? "-",
      date: `${formatOrderDate(row.created_at, i18n.language)} ${formatOrderTime(row.created_at, i18n.language)}`,
    }));
    const headers = [
      t("refunds.colRefundId"),
      t("refunds.colTxnId"),
      t("refunds.colCustomerOrder"),
      t("refunds.colAmount"),
      t("refunds.colType"),
      t("refunds.colStatus"),
      t("transactions.colDateTime"),
      t("refunds.colReason"),
    ];
    const rowsPerPage = 12;
    const pages = rows.length
      ? Array.from({ length: Math.ceil(rows.length / rowsPerPage) }, (_, index) => rows.slice(index * rowsPerPage, index * rowsPerPage + rowsPerPage))
      : [[]];

    for (let pageIndex = 0; pageIndex < pages.length; pageIndex += 1) {
      const pageRows = pages[pageIndex];
      const parts: string[] = [
        `<svg xmlns="http://www.w3.org/2000/svg" width="${pageWidth}" height="${pageHeight}" viewBox="0 0 ${pageWidth} ${pageHeight}">`,
        `<rect width="100%" height="100%" fill="#ffffff"/>`,
        `<style>text{font-family:Arial,'PingFang SC','Microsoft YaHei','Noto Sans CJK SC',sans-serif;dominant-baseline:alphabetic}</style>`,
        `<line x1="${margin}" y1="164" x2="${pageWidth - margin}" y2="164" stroke="#d1d5db" stroke-width="2"/>`,
        svgText([t("refunds.pageHeading")], margin + 24, 82, { size: 32, weight: 900, color: "#111827" }),
        svgText([`${t("refunds.dateRange")}: ${dateLabel}`], margin + 24, 120, { size: 17, weight: 700, color: "#475569" }),
        svgText([`${t("refunds.statUpdatedNow")} · ${pageIndex + 1}/${pages.length}`], margin + 24, 148, { size: 14, weight: 600, color: "#64748b" }),
      ];

      const summary = [
        { label: t("refunds.statTotalCount"), value: String(totalCount) },
        { label: t("refunds.statTotalAmount"), value: stats ? `RM ${Number(stats.totalAmount).toFixed(2)}` : "-" },
        { label: t("refunds.statTodayAmount"), value: stats ? `RM ${Number(stats.todayAmount).toFixed(2)}` : "-" },
      ];
      summary.forEach((card, index) => {
        const x = pageWidth - margin - 600 + index * 200;
        parts.push(svgText([card.label], x + 16, 105, { size: 12, weight: 800, color: "#64748b" }));
        parts.push(svgText([card.value], x + 16, 132, { size: 18, weight: 900, color: "#111827" }));
      });

      let y = 198;
      const headerHeight = 50;
      const rowHeight = 64;
      parts.push(`<rect x="${margin}" y="${y}" width="${tableWidth}" height="${headerHeight}" fill="#f3f4f6"/>`);
      let x = margin + 16;
      headers.forEach((header, index) => {
        parts.push(svgText(wrapPdfText(header, Math.floor((colWidths[index] - 12) / 13)).slice(0, 2), x + 10, y + 33, { size: 13, weight: 900, color: "#374151", lineHeight: 15 }));
        x += colWidths[index];
      });
      y += headerHeight + 34;

      if (!pageRows.length) {
        parts.push(svgText([t("common.noData", { defaultValue: "No data" })], margin + 32, y + 82, { size: 24, weight: 800, color: "#867461" }));
      }

      pageRows.forEach((row, index) => {
        const rowY = y + index * rowHeight;
        if (index % 2 === 0) {
          parts.push(`<rect x="${margin}" y="${rowY - 28}" width="${tableWidth}" height="${rowHeight}" fill="#f9fafb"/>`);
        }
        parts.push(`<line x1="${margin}" y1="${rowY + 36}" x2="${pageWidth - margin}" y2="${rowY + 36}" stroke="#e5e7eb" stroke-width="1"/>`);
        x = margin + 16;
        const orderCustomer = [row.customer, row.orderCode];
        const cells = [
          wrapPdfText(row.refundId, 10),
          wrapPdfText(row.txnId, 13),
          orderCustomer,
          wrapPdfText(`${row.amount}\n${row.method}`, 13),
          [row.typeLabel],
          [row.statusLabel],
          wrapPdfText(row.date, 14),
          wrapPdfText(row.reason, 34).slice(0, 2),
        ];
        cells.forEach((lines, cellIndex) => {
          parts.push(svgText(lines, x + 10, rowY, {
            size: cellIndex === 0 || cellIndex === 1 || cellIndex === 3 ? 15 : 14,
            weight: cellIndex === 0 || cellIndex === 1 || cellIndex === 3 ? 800 : 600,
            color: cellIndex === 3 ? "#111827" : "#334155",
            lineHeight: 18,
          }));
          x += colWidths[cellIndex];
        });
      });

      parts.push("</svg>");
      const image = await renderRefundPdfPageToPng(parts.join(""), pageWidth, pageHeight);
      if (pageIndex > 0) doc.addPage();
      doc.addImage(image, "PNG", 0, 0, pageWidthMm, pageHeightMm);
    }

    doc.save(`refund-report-${dayjs().format("YYYYMMDD-HHmm")}.pdf`);
  }

  const columns: ColumnsType<AdminRefundItem> = [
    {
      title: TH("refunds.colRefundId"),
      key: "rfd_id", width: 130,
      render: (_, row) => (
        <div>
          <div className="text-[13px] font-extrabold text-[#191c1d]">{refundDisplayId(row.id)}</div>
          <div className="text-[11px] text-[#867461]">
            {formatOrderDate(row.created_at, i18n.language)}<br />
            {formatOrderTime(row.created_at, i18n.language)}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colTxnId"),
      key: "txn_id", width: 160,
      render: (_, row) => (
        <div
          className="cursor-pointer"
          onClick={() => navigate(`/transactions/${row.transaction_id}?from=refunds`, { state: { activeNav: "/refunds" } })}
        >
          <div className="font-mono text-xs font-black text-[#191c1d]">
            {formatTransactionId(row.transaction_id)}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colCustomerOrder"),
      key: "customer", width: 160,
      render: (_, row) => (
        <div className="min-w-0">
          <div className="truncate text-sm font-black text-[#191c1d]">{row.order?.customer?.name ?? t("common.guest")}</div>
          <div className="mt-1 text-xs font-bold text-[#7a6f65]">#{row.order?.order_code ?? "—"}</div>
        </div>
      ),
    },
    {
      title: TH("refunds.colAmount"),
      key: "amount", width: 110,
      render: (_, row) => (
        <div>
          <div className="text-[15px] font-extrabold text-[#191c1d]">
            RM {Number(row.amount).toFixed(2)}
          </div>
          <div className="mt-0.5 text-[10px] text-[#867461]">
            {PAYMENT_I18N_KEYS[row.method] ? payLabel(row.method) : row.method}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colType"),
      key: "type", width: 100,
      render: (_, row) => <TypeBadge type={row.type} />,
    },
    {
      title: TH("refunds.colReason"),
      dataIndex: "reason", key: "reason", width: 140,
      render: (v: string) => <span className="text-xs text-[#534434]">{v}</span>,
    },
    {
      title: TH("refunds.colStatus"),
      key: "status", width: 130,
      render: (_, row) => <StatusPill status={row.status} />,
    },
    {
      title: TH("refunds.colAction"),
      key: "actions", width: 56, fixed: "right",
      render: (_, row) => {
        const items: MenuProps["items"] = [
          ...(row.status === "pending" ? [{
            key: "update",
            label: <span className="text-xs font-bold tracking-[0.5px]">{t("refunds.menuUpdateStatus").toUpperCase()}</span>,
            onClick: () => setUpdateTarget(row),
          }] : []),
          {
            key: "detail",
            label: <span className="text-xs font-bold tracking-[0.5px]">{t("refunds.menuViewDetails").toUpperCase()}</span>,
            onClick: () => navigate(`/refunds/${row.id}`),
          },
          {
            key: "order",
            label: <span className="text-xs font-bold tracking-[0.5px]">{t("refunds.menuViewOrders").toUpperCase()}</span>,
            onClick: () => navigate(`/orders/${row.order?.id ?? ""}`, { state: { activeNav: "/refunds" } }),
          },
        ];
        return (
          <Dropdown menu={{ items }} trigger={["click"]}>
            <button type="button" className="inline-flex cursor-pointer items-center justify-center border-none bg-transparent px-2 py-1 text-slate-500">
              <MoreOutlined className="text-lg" />
            </button>
          </Dropdown>
        );
      },
    },
  ];

  // ── Stat cards config ──
  const statCards = [
    {
      label: t("refunds.statTotalAmount").toUpperCase(),
      value: stats ? `RM ${Number(stats.totalAmount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}` : "—",
      sub: stats ? t("refunds.statSubVsLastMonth") : "",
    },
    {
      label: t("refunds.statTotalCount").toUpperCase(),
      value: stats ? String(stats.totalCount) : "—",
      sub: t("refunds.statAccumulatedMonth"),
    },
    {
      label: t("refunds.statPartialCount").toUpperCase(),
      value: stats ? String(stats.partialCount) : "—",
      sub: stats && stats.totalCount > 0
        ? t("refunds.statPartialPct", { pct: Math.round(stats.partialCount / stats.totalCount * 100) })
        : "",
    },
    {
      label: t("refunds.statTodayAmount").toUpperCase(),
      value: stats ? `RM ${Number(stats.todayAmount).toFixed(2)}` : "—",
      sub: t("refunds.statUpdatedNow"),
    },
  ];

  return (
    <AdminShell>
      <div className={REFUNDS_PAGE_CLASS}>
        <div className="mx-auto">
          <div ref={filterRef} className={REFUNDS_FILTER_CLASS}>
            <div className="mx-auto">
              <div className="mb-5 flex flex-wrap items-end justify-between gap-4">
                <div className="flex min-w-[220px] flex-col items-start gap-[9px]">
                  <div className="m-0 text-2xl font-black leading-8 tracking-[-0.6px] text-[#191c1d]">{t("refunds.pageHeading")}</div>
                  <div className="flex w-full items-center gap-2">
                    <span className="inline-block size-2 shrink-0 rounded-full bg-[#006c49]" />
                    <span className="text-xs font-medium leading-4 text-[#534434]">{t("refunds.statUpdatedNow")}</span>
                  </div>
                </div>

                <div className="flex w-full flex-wrap items-center justify-end gap-3 sm:w-auto">
                  <div className="relative w-full max-w-[420px] min-w-[260px] sm:w-[360px] xl:w-[420px]">
                    <Search className="pointer-events-none absolute left-4 top-1/2 size-4 -translate-y-1/2 text-[#867461]" />
                    <input
                      type="text"
                      value={search}
                      onChange={(event) => {
                        setSearch(event.target.value);
                        setPage(1);
                      }}
                      placeholder={t("refunds.placeholderSearch")}
                      className="h-11 w-full rounded-lg border border-[#e7e1db] bg-white pl-11 pr-11 text-sm font-semibold text-[#191c1d] outline-none shadow-[0_12px_28px_rgba(25,28,29,0.06)] placeholder:text-[#867461] focus:border-[#ea580c] focus:ring-4 focus:ring-[#ea580c]/10"
                    />
                    {search && (
                      <button
                        type="button"
                        onClick={() => {
                          setSearch("");
                          setPage(1);
                        }}
                        className="absolute right-3 top-1/2 flex size-6 -translate-y-1/2 items-center justify-center rounded-full border-none bg-[#f3f4f5] text-[#534434] transition hover:bg-[#ffedd5] hover:text-[#ea580c]"
                        aria-label="Clear search"
                      >
                        <X className="size-3.5" />
                      </button>
                    )}
                  </div>
                  <button
                    type="button"
                    onClick={exportRefundsPdf}
                    className="inline-flex h-11 items-center justify-center gap-2 rounded-lg border border-[#d7eadf] bg-white px-4 text-sm font-black text-[#006c49] shadow-[0_12px_28px_rgba(25,28,29,0.05)] transition hover:border-[#006c49] hover:bg-[#ecfdf5]"
                  >
                    <DownloadOutlined />
                    {t("refunds.exportPdf")}
                  </button>
                </div>
              </div>

              <div className="mb-5 grid grid-cols-[repeat(auto-fit,minmax(220px,1fr))] gap-4">
                {statCards.map((card, index) => (
                  <div key={card.label} className="rounded-2xl border border-[#e8ecef] bg-white p-5 shadow-[0_12px_28px_rgba(15,23,42,0.04)]">
                    <div className={`mb-4 h-1 w-10 rounded-full ${index === 0 ? "bg-[#d86b19]" : index === 1 ? "bg-[#00766a]" : index === 2 ? "bg-[#d44242]" : "bg-[#384044]"}`} />
                    <div className="mb-3 text-[11px] font-black uppercase tracking-[0.8px] text-[#7a6f65]">{card.label}</div>
                    <div className="text-[28px] font-black leading-[1.2] text-[#191c1d]">{card.value}</div>
                    {card.sub && <div className="mt-2 text-xs font-bold text-[#7a6f65]">{card.sub}</div>}
                  </div>
                ))}
              </div>

              <div className="flex items-center gap-3 rounded-lg border border-[#eee8e2] bg-white/85 p-2 shadow-[0_12px_30px_rgba(25,28,29,0.05)] backdrop-blur max-lg:flex-col max-lg:items-stretch">
                <div className="grid min-w-0 flex-1 grid-cols-[repeat(auto-fit,minmax(150px,1fr))] gap-2">
                  <div className="relative">
                    <RangePicker
                      value={dateRange ? [dayjs(dateRange[0]).format("YYYY-MM-DD"), dayjs(dateRange[1]).format("YYYY-MM-DD")] : undefined}
                      className={`h-10 w-full ${dateRange ? "pr-12" : ""}`}
                      onChange={(value, s) => {
                        const [from, to] = (s ?? value) as [string, string];
                        setDateRange(from && to ? [
                          dayjs(from).startOf("day").toISOString(),
                          dayjs(to).endOf("day").toISOString(),
                        ] : null);
                        setPage(1);
                      }}
                    />
                    {dateRange && (
                      <button
                        type="button"
                        onClick={() => {
                          setDateRange(null);
                          setPage(1);
                        }}
                        className="absolute right-2.5 top-1/2 flex size-6 -translate-y-1/2 items-center justify-center rounded-full border-none bg-[#f3f4f5] text-[#534434] transition hover:bg-[#ffedd5] hover:text-[#ea580c]"
                        aria-label="Reset date filter"
                      >
                        <X className="size-3.5" />
                      </button>
                    )}
                  </div>
                  <Select
                    value={type}
                    onChange={(v) => { setType(v as string | undefined); setPage(1); }}
                    allowClear
                    className="h-10 min-h-10 w-full"
                    placeholder={t("refunds.placeholderAllTypes")}
                    options={[
                      { value: "full", label: t("refunds.typeFull") },
                      { value: "partial", label: t("refunds.typePartial") },
                    ]}
                  />
                  <Select
                    value={method}
                    onChange={(v) => { setMethod(v as string | undefined); setPage(1); }}
                    allowClear
                    className="h-10 min-h-10 w-full"
                    placeholder={t("refunds.placeholderAllMethods")}
                    options={Object.keys(PAYMENT_I18N_KEYS).map((v) => ({ value: v, label: payLabel(v) }))}
                  />
                  <Select
                    value={status}
                    onChange={(v) => { setStatus(v as string | undefined); setPage(1); }}
                    allowClear
                    className="h-10 min-h-10 w-full"
                    placeholder={t("refunds.placeholderAllStatus")}
                    options={[
                      { value: "pending", label: t("refunds.statusPending") },
                      { value: "success", label: t("refunds.statusSuccess") },
                      { value: "rejected", label: t("refunds.statusRejectedPill") },
                      { value: "failed", label: t("refunds.statusFailed") },
                    ]}
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Spacer, NOT part of the scroll container below — pushes the table's own
              bounding box to start below the fixed filter panel. Scrolling *inside*
              a box that also contains this padding would scroll the padding away too,
              letting rows travel back up underneath the fixed panel. */}
          <div style={{ height: filterHeight ? filterHeight + 24 : 320 }} />
          <div
            className="border-none bg-transparent shadow-none"
            style={{
              maxHeight: filterHeight ? `calc(100vh - 64px - ${filterHeight + 24}px)` : undefined,
              overflowY: filterHeight ? "auto" : "visible",
            }}
          >
            <Table<AdminRefundItem>
              columns={columns}
              dataSource={refunds}
              rowKey="id"
              loading={isLoading}
              rowClassName={rowClassName}
              size="middle"
              scroll={{ x: 1000 }}
              pagination={{ current: page, total: totalCount, pageSize: 10, showAlways: true, onChange: (p) => setPage(p) }}
            />
          </div>
        </div>
      </div>

      {updateTarget && (
        <UpdateStatusModal
          refund={updateTarget}
          onClose={() => setUpdateTarget(null)}
        />
      )}
    </AdminShell>
  );
}
