// @ts-nocheck
import { useState, useMemo } from "react";
import {
  Button, Modal, Form, Input, InputNumber, Select, Switch, Space, Typography, Tag,
  Popconfirm, message, Tooltip, Table,
} from "../components/admin-ui";
import {
  PlusOutlined, EditOutlined, DeleteOutlined, ApiOutlined, CarOutlined,
} from "../components/admin-icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "../components/admin-ui";
import type { DeliveryProvider } from "@kawkaw/shared";
import { tokens } from "../styles/tokens";
import { AdminShell } from "../layouts/AdminShell";
import {
  useDeliveryProviders, useCreateDeliveryProvider,
  useUpdateDeliveryProvider, useDeleteDeliveryProvider, useTestDeliveryProvider,
} from "../api/hooks";

const { Title, Text } = Typography;
const { color: T } = tokens;

const PROVIDER_COLOR: Record<string, string> = {
  lalamove: "orange", grabexpress: "green", foodpanda: "magenta",
  pandago: "red", myposrider: "blue", manual: "default", custom: "geekblue",
};

const PROVIDER_ICONS: Record<string, string> = {
  lalamove: "🚚", grabexpress: "🚗", foodpanda: "🐼",
  pandago: "🐼", myposrider: "🛵", manual: "👤", custom: "⚙️",
};

// Known base URLs per provider — used to auto-fill base_url when Sandbox Mode
// is toggled, so an admin never has to hand-type (or mistype) a provider's
// API host. Only providers with well-known REST endpoints are listed; others
// fall back to manual entry.
const PROVIDER_URLS: Record<string, { sandbox: string; production: string }> = {
  lalamove: { sandbox: "https://rest.sandbox.lalamove.com", production: "https://rest.lalamove.com" },
};

export function DeliveryProvidersScreen() {
  const { t } = useTranslation();
  const providerOptions = useMemo(
    () =>
      (
        [
          ["lalamove", "providerLalamove"],
          ["grabexpress", "providerGrabexpress"],
          ["foodpanda", "providerFoodpanda"],
          ["pandago", "providerPandago"],
          ["myposrider", "providerMyposrider"],
          ["manual", "providerManual"],
          ["custom", "providerCustom"],
        ] as const
      ).map(([value, key]) => ({ value, label: t(`deliveryProviders.${key}`) })),
    [t],
  );
  const providerLabel = (v: string) => providerOptions.find(p => p.value === v)?.label ?? v;
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<DeliveryProvider | null>(null);
  const [form] = Form.useForm();

  // Auto-fill base_url from the known sandbox/production pair whenever the
  // provider or the Sandbox Mode switch changes — an admin should never have
  // to hand-type (or mistype) a provider's API host.
  const applyKnownUrl = (provider: string | undefined, isSandbox: boolean) => {
    const known = provider ? PROVIDER_URLS[provider] : undefined;
    if (known) form.setFieldValue("base_url", isSandbox ? known.sandbox : known.production);
  };

  const { data, isLoading } = useDeliveryProviders();
  const createProvider = useCreateDeliveryProvider();
  const updateProvider = useUpdateDeliveryProvider();
  const deleteProvider = useDeleteDeliveryProvider();
  const testProvider = useTestDeliveryProvider();

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (row: DeliveryProvider) => {
    setEditing(row);
    form.setFieldsValue({
      ...row,
      coverage_km: row.coverage_km ? Number(row.coverage_km) : null,
    });
    setModalOpen(true);
  };

  const onSave = async (values: Record<string, unknown>) => {
    try {
      if (editing) {
        await updateProvider.mutateAsync({ id: editing.id, ...values });
        void message.success(t("deliveryProviders.updateSuccess"));
      } else {
        await createProvider.mutateAsync(values);
        void message.success(t("deliveryProviders.createSuccess"));
      }
      setModalOpen(false);
    } catch { void message.error(t("deliveryProviders.saveFailed")); }
  };

  const onDelete = async (id: string) => {
    try { await deleteProvider.mutateAsync(id); void message.success(t("deliveryProviders.deleteSuccess")); }
    catch { void message.error(t("deliveryProviders.deleteFailed")); }
  };

  const onTest = async (id: string) => {
    try {
      const res = await testProvider.mutateAsync(id);
      const result = (res as { data?: { success: boolean; message: string; latency_ms?: number } }).data;
      if (result?.success) {
        void message.success(
          result.latency_ms != null
            ? t("common.connectionTestOkWithLatency", { message: result.message, ms: result.latency_ms })
            : t("common.connectionTestOk", { message: result.message }),
        );
      } else {
        void message.error(
          t("common.connectionTestFailed", {
            message: result?.message ?? t("transactions.testFailedGeneric"),
          }),
        );
      }
    } catch { void message.error(t("deliveryProviders.testFailed")); }
  };

  const items = (data as { data?: DeliveryProvider[] } | undefined)?.data ?? [];

  const columns: ColumnsType<DeliveryProvider> = [
    {
      title: t("deliveryProviders.colProvider"), dataIndex: "provider", key: "provider", width: 160,
      render: (v: string) => (
        <Tag color={PROVIDER_COLOR[v] ?? "default"}>
          {PROVIDER_ICONS[v] ?? "📦"} {providerLabel(v)}
        </Tag>
      ),
    },
    {
      title: t("deliveryProviders.colDisplayName"), dataIndex: "display_name", key: "display_name",
      render: (v: string) => <Text strong>{v}</Text>,
    },
    {
      title: t("deliveryProviders.colApiKey"), dataIndex: "api_key", key: "api_key", width: 160,
      render: (v: string | null) => v ? <Text code style={{ fontSize: 11 }}>{v}</Text> : <Text type="secondary">—</Text>,
    },
    {
      title: t("deliveryProviders.colBaseUrl"), dataIndex: "base_url", key: "base_url", width: 200,
      render: (v: string | null) => v ? <Text style={{ fontSize: 11 }}>{v}</Text> : <Text type="secondary">—</Text>,
    },
    {
      title: t("deliveryProviders.formSandboxMode", "Sandbox Mode"), dataIndex: "is_sandbox", key: "is_sandbox", width: 110,
      render: (v: boolean) => (
        <Tag color={v ? "gold" : "green"}>{v ? t("deliveryProviders.sandbox", "Sandbox") : t("deliveryProviders.production", "Production")}</Tag>
      ),
    },
    {
      title: t("deliveryProviders.colCoverage"), dataIndex: "coverage_km", key: "coverage_km", width: 110,
      render: (v: string | null) => v ? (
        <Text>{t("deliveryProviders.coverageKm", { km: Number(v).toFixed(0) })}</Text>
      ) : <Text type="secondary">—</Text>,
    },
    {
      title: t("deliveryProviders.colStatus"), dataIndex: "is_active", key: "active", width: 90,
      render: (v: boolean) => <Tag color={v ? "success" : "default"}>{v ? t("common.yes") : t("common.no")}</Tag>,
    },
    {
      title: "", key: "actions", width: 140, fixed: "right" as const,
      render: (_: unknown, row: DeliveryProvider) => (
        <Space>
          <Tooltip title={t("deliveryProviders.testConnection")}>
            <Button size="small" icon={<ApiOutlined />} loading={testProvider.isPending} onClick={() => void onTest(row.id)} />
          </Tooltip>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm title={t("deliveryProviders.confirmDelete")} onConfirm={() => void onDelete(row.id)} okType="danger" placement="left">
            <Button size="small" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px 40px", background: T.bg, minHeight: "100vh" }}>
        <div style={{ maxWidth: 1480, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", gap: 18, marginBottom: 22, flexWrap: "wrap" }}>
            <div>
              <div style={{ display: "inline-flex", alignItems: "center", gap: 8, padding: "6px 12px", borderRadius: 999, background: T.brandLight, color: T.brand, fontSize: 11, fontWeight: 900, textTransform: "uppercase", marginBottom: 10 }}>
                <CarOutlined /> {items.length.toLocaleString()}
              </div>
              <h1 style={{ margin: 0, fontSize: 32, lineHeight: 1.1, fontWeight: 900, color: T.textDark }}>{t("deliveryProviders.title")}</h1>
              <div style={{ marginTop: 8, fontSize: 13, color: T.textMuted, fontWeight: 600 }}>{t("deliveryProviders.subtitle")}</div>
            </div>
            <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
              style={{ background: T.brand, borderColor: T.brand, height: 44, borderRadius: 12, fontWeight: 800, paddingInline: 20, boxShadow: "0 12px 24px rgba(249,115,22,0.18)" }}>
              {t("deliveryProviders.addProvider")}
            </Button>
          </div>

          <div style={{ background: T.surface, borderRadius: 16, border: "1px solid #E5E7EB", overflow: "hidden", boxShadow: "0 14px 34px rgba(15,23,42,0.05)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #F3F4F6" }}>
              <div style={{ fontSize: 16, fontWeight: 900, color: T.textDark }}>{t("deliveryProviders.title")}</div>
              <div style={{ fontSize: 12, fontWeight: 700, color: T.textMuted }}>{items.length.toLocaleString()}</div>
            </div>
            <Table<DeliveryProvider>
              columns={columns}
              dataSource={items}
              rowKey="id"
              loading={isLoading}
              size="middle"
              pagination={{ pageSize: 10 }}
              scroll={{ x: 1000 }}
            />
          </div>
        </div>
      </div>

      <Modal
        open={modalOpen}
        title={
          <Space>
            <CarOutlined />
            {editing ? t("deliveryProviders.editTitle") : t("deliveryProviders.newTitle")}
          </Space>
        }
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okText={t("common.save")}
        okButtonProps={{ style: { background: T.brandAmber, borderColor: T.brandAmber }, loading: createProvider.isPending || updateProvider.isPending }}
        width={600}
        maskClosable={false}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="provider" label={t("deliveryProviders.formProvider")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <Select options={providerOptions} placeholder={t("deliveryProviders.phSelectProvider")}
                onChange={(v: string) => applyKnownUrl(v, form.getFieldValue("is_sandbox") ?? true)} />
            </Form.Item>
            <Form.Item name="display_name" label={t("deliveryProviders.formDisplayName")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <Input placeholder={t("deliveryProviders.phDisplayName")} />
            </Form.Item>
          </Space>
          <Form.Item name="is_sandbox" label={t("deliveryProviders.formSandboxMode", "Sandbox Mode")} valuePropName="checked" initialValue={true}
            extra={t("deliveryProviders.sandboxModeHint", "Sandbox uses the provider's test environment — switch off only once you have real production credentials.")}>
            <Switch checkedChildren={t("deliveryProviders.sandbox", "Sandbox")} unCheckedChildren={t("deliveryProviders.production", "Production")}
              onChange={(checked: boolean) => applyKnownUrl(form.getFieldValue("provider"), checked)} />
          </Form.Item>
          <Form.Item name="api_key" label={t("deliveryProviders.formApiKey")}>
            <Input.Password placeholder={t("deliveryProviders.formApiKeyPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="api_secret" label={t("deliveryProviders.formApiSecret")}>
            <Input.Password placeholder={t("deliveryProviders.formApiSecretPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="webhook_secret" label={t("deliveryProviders.formWebhookSecret")}>
            <Input.Password placeholder={t("deliveryProviders.formWebhookSecretPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="base_url" label={t("deliveryProviders.formBaseUrl")}>
            <Input placeholder={t("deliveryProviders.phBaseUrl")} />
          </Form.Item>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="coverage_km" label={t("deliveryProviders.formCoverageKm")} style={{ flex: 1 }}>
              <InputNumber min={0} max={200} precision={0} addonAfter={t("deliveryProviders.unitKm")} style={{ width: "100%" }} />
            </Form.Item>
            <Form.Item name="sort_order" label={t("deliveryProviders.formSortOrder")} initialValue={0} style={{ flex: 1 }}>
              <Input type="number" min={0} />
            </Form.Item>
          </Space>
          <Form.Item name="is_active" label={t("deliveryProviders.formIsActive")} valuePropName="checked" initialValue={true}>
            <Switch checkedChildren={t("common.yes")} unCheckedChildren={t("common.no")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
