export function getOrderStatusTheme(status: string | null | undefined) {
  return ORDER_STATUS_THEME[normalizeOrderStatus(status)] ?? FALLBACK_ORDER_STATUS_THEME;
}

export function getOrderCustomerDisplay(order: OrderLike) {
  const contactPart = order.special_note?.split("—")[0]?.trim();
  const walkInMatch = contactPart?.match(/^Walk-in:\s*(.+?)(?:\s*\((.+)\))?$/i);
  return {
    name: order.customer?.name ?? order.customer_name ?? walkInMatch?.[1]?.trim() ?? null,
    phone: order.customer?.phone ?? order.customer_phone ?? walkInMatch?.[2]?.trim() ?? null,
  };
}

export function getOrderStatusAction(order: OrderLike) {
  const status = normalizeOrderStatus(order.status);
  const type = order.type;
  if (status === "preparing") return { actionKey: "mark_ready", nextStatus: "ready" };
  if (status === "ready" && type === "pickup") return { actionKey: "picked_up", nextStatus: "completed" };
  if (status === "ready" && type === "delivery") return { actionKey: "out_for_delivery", nextStatus: "out_for_delivery" };
  if (status === "out_for_delivery" || status === "in_transit") return { actionKey: "delivered", nextStatus: "delivered" };
  return null;
}

export function normalizeOrderStatus(status: string | null | undefined): string {
  const normalized = String(status ?? "").trim();
  const lower = normalized.replace(/-/g, "_").replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
  return lower.replace(/^_/, "");
}
