// @ts-nocheck
import { useState, useEffect, useRef } from "react";
import { Input, Card, App, Spin, Button, Typography } from "../components/admin-ui";
import { useTranslation } from "react-i18next";
import { useAdminSettings, useUpdateSettings } from "../api/hooks";
import { AdminShell } from "../layouts/AdminShell";

const { Text } = Typography;

/**
 * Configures the customer-app-only per-item pricing markup: items priced at
 * or below the threshold get a flat fee added; items above it get a
 * percentage surcharge instead. Applies to online delivery and customer-app
 * self-pickup orders — never to POS walk-in orders (waived entirely there),
 * and never displayed in stall-app/pos-app (they show the plain menu price).
 */
export function PricingRulesScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const { data, isLoading } = useAdminSettings();
  const update = useUpdateSettings();

  const [threshold, setThreshold] = useState("15.00");
  const [flatFee, setFlatFee] = useState("0.50");
  const [percent, setPercent] = useState("3.5");
  const [addonPercent, setAddonPercent] = useState("3.5");
  const [saving, setSaving] = useState(false);

  const hydrated = useRef(false);
  const settings = data?.data as Record<string, unknown> | undefined;
  useEffect(() => {
    if (hydrated.current || !settings) return;
    if (settings.price_markup_threshold != null) setThreshold(Number(settings.price_markup_threshold).toFixed(2));
    if (settings.price_markup_flat_fee != null) setFlatFee(Number(settings.price_markup_flat_fee).toFixed(2));
    if (settings.price_markup_percent != null) setPercent(Number((Number(settings.price_markup_percent) * 100).toFixed(4)).toString());
    if (settings.addon_markup_percent != null) setAddonPercent(Number((Number(settings.addon_markup_percent) * 100).toFixed(4)).toString());
    hydrated.current = true;
  }, [settings]);

  const handleSave = async () => {
    try {
      setSaving(true);
      await update.mutateAsync({
        price_markup_threshold: parseFloat(threshold) || 0,
        price_markup_flat_fee: parseFloat(flatFee) || 0,
        price_markup_percent: (parseFloat(percent) || 0) / 100,
        addon_markup_percent: (parseFloat(addonPercent) || 0) / 100,
      });
      void message.success(t("pricingRules.saveSuccess", "Pricing rules saved"));
    } catch {
      void message.error(t("pricingRules.saveFailed", "Failed to save pricing rules"));
    } finally {
      setSaving(false);
    }
  };

  const exampleLow = 12.0;
  const exampleHigh = 16.0;
  const lowResult = exampleLow <= (parseFloat(threshold) || 0) ? exampleLow + (parseFloat(flatFee) || 0) : exampleLow + exampleLow * ((parseFloat(percent) || 0) / 100);
  const highResult = exampleHigh <= (parseFloat(threshold) || 0) ? exampleHigh + (parseFloat(flatFee) || 0) : exampleHigh + exampleHigh * ((parseFloat(percent) || 0) / 100);

  return (
    <AdminShell>
      <div className="min-h-screen bg-[#f8f9fa] px-8 pb-10 pt-7">
        <div className="mx-auto max-w-[720px]">
          <div className="mb-[22px]">
            <h1 className="m-0 text-[32px] font-black leading-[1.1] text-[#191c1d]">
              {t("pricingRules.title", "Pricing Rules")}
            </h1>
            <div className="mt-2 text-[13px] font-semibold text-[#6b7280]">
              {t("pricingRules.subtitle", "Per-item markup shown to customer-app orders (delivery + self-pickup). Walk-in POS orders always use the original menu price.")}
            </div>
          </div>

          {isLoading ? (
            <div className="p-10 text-center"><Spin /></div>
          ) : (
            <Card className="overflow-hidden rounded-2xl border border-[#e5e7eb] p-6 shadow-[0_14px_34px_rgba(15,23,42,0.05)]">
              <div style={{ marginBottom: 18 }}>
                <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#6b7280", marginBottom: 6 }}>
                  {t("pricingRules.thresholdLabel", "Price threshold (RM)")}
                </div>
                <Input value={threshold} onChange={(e) => setThreshold(e.target.value)} style={{ height: 44 }} />
                <Text type="secondary" style={{ fontSize: 12 }}>
                  {t("pricingRules.thresholdHint", "Items priced at or below this amount get the flat fee. Items above it get the percentage instead.")}
                </Text>
              </div>

              <div style={{ marginBottom: 18 }}>
                <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#6b7280", marginBottom: 6 }}>
                  {t("pricingRules.flatFeeLabel", "Flat fee for items ≤ threshold (RM)")}
                </div>
                <Input value={flatFee} onChange={(e) => setFlatFee(e.target.value)} style={{ height: 44 }} />
              </div>

              <div style={{ marginBottom: 24 }}>
                <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#6b7280", marginBottom: 6 }}>
                  {t("pricingRules.percentLabel", "Surcharge for items > threshold (%)")}
                </div>
                <Input value={percent} onChange={(e) => setPercent(e.target.value)} style={{ height: 44 }} />
              </div>

              <div style={{ borderTop: "1px solid #e5e7eb", margin: "22px 0", paddingTop: 22 }}>
                <div style={{ fontSize: 15, fontWeight: 800, color: "#191c1d", marginBottom: 4 }}>
                  {t("pricingRules.addonSectionTitle", "Add-on markup rate")}
                </div>
                <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 14 }}>
                  {t("pricingRules.addonSectionSub", "Applied to every paid add-on's own cost individually, regardless of which branch the base item's price took above. Independent from the base-item rule.")}
                </div>
                <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#6b7280", marginBottom: 6 }}>
                  {t("pricingRules.addonPercentLabel", "Add-on markup (%)")}
                </div>
                <Input value={addonPercent} onChange={(e) => setAddonPercent(e.target.value)} style={{ height: 44 }} />
              </div>

              <div style={{ background: "#fff7ed", border: "1px solid #fed7aa", borderRadius: 10, padding: "14px 16px", marginBottom: 24 }}>
                <div style={{ fontSize: 12, fontWeight: 800, color: "#c2410c", marginBottom: 8, textTransform: "uppercase", letterSpacing: 0.5 }}>
                  {t("pricingRules.exampleTitle", "Live example")}
                </div>
                <div style={{ fontSize: 13, color: "#7c2d12" }}>
                  {t("pricingRules.exampleLow", "RM {{price}} item → customer sees RM {{result}} (≤ threshold, flat fee)", {
                    price: exampleLow.toFixed(2), result: lowResult.toFixed(2),
                  })}
                </div>
                <div style={{ fontSize: 13, color: "#7c2d12", marginTop: 4 }}>
                  {t("pricingRules.exampleHigh", "RM {{price}} item → customer sees RM {{result}} (> threshold, {{percent}}% surcharge)", {
                    price: exampleHigh.toFixed(2), result: highResult.toFixed(2), percent: percent || 0,
                  })}
                </div>
                <div style={{ fontSize: 13, color: "#7c2d12", marginTop: 4 }}>
                  {t("pricingRules.exampleAddon", "RM {{price}} add-on → customer sees RM {{result}} ({{percent}}% add-on markup, always applied)", {
                    price: (1).toFixed(2), result: (1 + (parseFloat(addonPercent) || 0) / 100).toFixed(2), percent: addonPercent || 0,
                  })}
                </div>
              </div>

              <Button type="primary" loading={saving} onClick={() => void handleSave()}
                style={{ background: "#f97316", borderColor: "#f97316", height: 44, borderRadius: 10, fontWeight: 800, paddingInline: 24 }}>
                {t("common.save", "Save")}
              </Button>
            </Card>
          )}
        </div>
      </div>
    </AdminShell>
  );
}
